package com.goldendps;

import com.goldendps.model.BarrowsRun;
import com.goldendps.model.FightTracker;
import com.goldendps.model.Format;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Barrows runs in the game: brother hits and deaths, the chest message, and saving the run to the
 * RS profile so it survives a client restart. The run rules are in {@link BarrowsRun}.
 * Client thread, except {@link #clientClosed}.
 */
@Slf4j
@Singleton
class BarrowsTracker
{
	/** Game message when you open the Barrows chest. */
	private static final String CHEST_MESSAGE = "Your Barrows chest count is";
	/** RS profile key of the run that is going on. */
	private static final String SAVE_KEY = "barrowsRun";
	/** Save a running run once a minute (and on every start, kill and logout), so a crash loses little. */
	private static final int SAVE_TICKS = 100;

	private final ConfigManager configManager;
	private final Gson gson;
	private final BarrowsRun run = new BarrowsRun();
	private boolean loadAfterLogin;
	/** The live run time for the overlay and the panel, or null without a run. */
	private volatile String liveTime;
	private volatile boolean paused;

	@Inject
	BarrowsTracker(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/** You hit an NPC. */
	void hit(long now, String npcName)
	{
		if (run.hit(now, npcName))
		{
			save(now);
		}
	}

	/** An NPC died. */
	void died(long now, String npcName)
	{
		if (BarrowsRun.isBrother(npcName))
		{
			run.died(npcName);
			save(now);
		}
	}

	/** A game message: the chest adds the run to the fights. */
	void gameMessage(long now, String message, FightTracker tracker)
	{
		if (!message.startsWith(CHEST_MESSAGE))
		{
			return;
		}
		BarrowsRun.Result r = run.chestOpened(now);
		if (r != null)
		{
			tracker.addRun(BarrowsRun.NAME, r.startMs, r.endMs, r.activeMs, t -> BarrowsRun.isBrother(t.name),
				"Chest opened");
			save(now);
		}
	}

	/** The saved run is loaded on the next tick: the RS profile is set by then. */
	void loggedIn()
	{
		loadAfterLogin = true;
	}

	/** Logout or world hop: the clock stops and the run is saved for this account. */
	void loggedOut(long now)
	{
		run.loggedOut(now);
		save(now);
		run.clear();
		liveTime = null;
	}

	/** Not on the client thread, but the game loop has stopped. After a logout the run was saved already. */
	void clientClosed(long now)
	{
		if (run.isRunning())
		{
			run.loggedOut(now);
			save(now);
		}
	}

	void tick(long now, int tick)
	{
		if (loadAfterLogin)
		{
			loadAfterLogin = false;
			load();
		}
		if (run.isRunning() && tick % SAVE_TICKS == 0)
		{
			save(now);
		}
		paused = run.isPaused(now);
		liveTime = run.isRunning() ? Format.duration(run.activeMs(now)) : null;
	}

	String liveTime()
	{
		return liveTime;
	}

	boolean isPaused()
	{
		return paused;
	}

	private void save(long now)
	{
		BarrowsRun.Saved s = run.save(now);
		if (s == null)
		{
			configManager.unsetRSProfileConfiguration(GoldenDpsConfig.STATE_GROUP, SAVE_KEY);
		}
		else
		{
			configManager.setRSProfileConfiguration(GoldenDpsConfig.STATE_GROUP, SAVE_KEY, gson.toJson(s));
		}
	}

	/** Takes over the run saved for this account; its clock starts again at the next brother hit. */
	private void load()
	{
		if (!run.isRunning())
		{
			String json = configManager.getRSProfileConfiguration(GoldenDpsConfig.STATE_GROUP, SAVE_KEY);
			try
			{
				run.restore(json == null ? null : gson.fromJson(json, BarrowsRun.Saved.class));
			}
			catch (JsonParseException ex)
			{
				log.warn("Could not read the saved Barrows run", ex);
			}
		}
	}
}

package com.goldendps;

import com.goldendps.model.Fight;
import com.goldendps.model.TargetStats;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;

/** How far a boss is from dead, from its health bar. Client thread only. */
class BossHealth
{
	private final Client client;

	BossHealth(Client client)
	{
		this.client = client;
	}

	/**
	 * The part of the boss's health that is gone (0 to 1), or -1 when it is not known: no health bar,
	 * not in view, or several living bosses (Dagannoth Kings), where one bar says little.
	 */
	double done(Fight boss)
	{
		TargetStats alive = null;
		for (TargetStats t : boss.targets.values())
		{
			if (t.boss && t.engaged && !t.died)
			{
				if (alive != null)
				{
					return -1;
				}
				alive = t;
			}
		}
		NPC npc = alive == null ? null : npc(alive.key);
		if (npc == null || npc.getHealthScale() <= 0 || npc.getHealthRatio() < 0)
		{
			return -1;
		}
		return 1 - (double) npc.getHealthRatio() / npc.getHealthScale();
	}

	/** The NPC behind a target key ("world:index") in your scene, or null. */
	private NPC npc(String targetKey)
	{
		int split = targetKey.indexOf(':');
		WorldView view = client.getTopLevelWorldView();
		if (split < 0 || view == null || !targetKey.startsWith(client.getWorld() + ":"))
		{
			return null;
		}
		return view.npcs().byIndex(Integer.parseInt(targetKey.substring(split + 1)));
	}
}

package com.goldendps;

import com.goldendps.model.FightReport;

/** The boss meter as the overlay draws it. */
final class BossMeter
{
	final FightReport report;
	final boolean dead;
	/** No boss hits for the pause time: the boss clock stands still. */
	final boolean paused;
	/** "NEW PB!", "PB 1:10" or null. */
	final String pb;
	/** While the boss lives: the projected kill time minus the PB (negative = faster), or null. */
	final Long paceMs;

	BossMeter(FightReport report, boolean dead, boolean paused, String pb, Long paceMs)
	{
		this.report = report;
		this.dead = dead;
		this.paused = paused;
		this.pb = pb;
		this.paceMs = paceMs;
	}
}

package com.goldendps;

import javax.inject.Inject;
import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

/** Local chat messages (only visible to you). */
class ChatNotifier
{
	private static final String PREFIX = "GoldenDPS: ";
	private static final String LEAVE_COLOR = "c27c00";
	private static final String KICK_COLOR = "d42020";

	/** "<col=" plus six hex digits plus ">" */
	private static final int COLOR_TAG_LENGTH = 12;

	private final Client client;
	private final ChatMessageManager chatMessageManager;
	private final GoldenDpsConfig config;

	@Inject
	ChatNotifier(Client client, ChatMessageManager chatMessageManager, GoldenDpsConfig config)
	{
		this.client = client;
		this.chatMessageManager = chatMessageManager;
		this.config = config;
	}

	/** Info and good news (joined, raid started) in the color the player picked; leaving and kicks keep theirs. */
	void info(String text)
	{
		send(colored(chatHex(), PREFIX + text));
	}

	void left(String text)
	{
		send(colored(LEAVE_COLOR, PREFIX + text));
	}

	void kicked(String text)
	{
		send(colored(KICK_COLOR, PREFIX + text));
	}

	/** The chat color changed: give the info messages already in the chatbox the new color. Client thread. */
	void recolorOldMessages()
	{
		ChatLineBuffer buffer = client.getChatLineMap().get(ChatMessageType.CONSOLE.getType());
		if (buffer == null)
		{
			return;
		}
		MessageNode[] lines = buffer.getLines();
		for (int i = 0; i < buffer.getLength(); i++)
		{
			String text = lines[i] == null ? null : lines[i].getRuneLiteFormatMessage();
			if (isInfo(text))
			{
				lines[i].setRuneLiteFormatMessage("<col=" + chatHex() + ">" + text.substring(COLOR_TAG_LENGTH));
			}
		}
		client.refreshChat();
	}

	/** A GoldenDPS message in the chat color (not a leave or kick, which keep their own colors). */
	static boolean isInfo(String text)
	{
		return text != null && text.startsWith("<col=") && text.startsWith(PREFIX, COLOR_TAG_LENGTH)
			&& !text.startsWith(LEAVE_COLOR, 5) && !text.startsWith(KICK_COLOR, 5);
	}

	private String chatHex()
	{
		return String.format("%06x", config.chatColor().getRGB() & 0xffffff);
	}

	private static String colored(String hex, String text)
	{
		return "<col=" + hex + ">" + text + "</col>";
	}

	private void send(String text)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(text)
			.build());
	}
}

package com.goldendps;

import com.goldendps.model.AttackSource;
import com.goldendps.model.Fight;
import com.goldendps.model.FightTracker;
import com.goldendps.model.HitAttributor;
import com.goldendps.model.PlayerKind;
import com.goldendps.model.TargetMatcher;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.party.PartyService;

/**
 * Turns hitsplats into damage for the fight, and attacks (animations, spell casts, special
 * attacks) into the source of your hits and the owner of other players' hits. Client thread only.
 */
class CombatEvents
{
	private static final int EAT_ANIMATION = 829;

	private final Client client;
	private final PartyService partyService;
	private final GoldenDpsConfig config;
	private final FightTracker tracker;
	private final Bosses bosses;
	private final TargetMatcher matcher;
	private final LocalHealing healing;
	private final BarrowsTracker barrows;
	private final PartyManager party;
	private final PartyUpdates partyUpdates;

	private final HitAttributor attributor = new HitAttributor();
	private final AttackSource attackSource = new AttackSource();
	private int lastSpecEnergy = -1;

	CombatEvents(Client client, PartyService partyService, GoldenDpsConfig config, FightTracker tracker, Bosses bosses, TargetMatcher matcher,
		LocalHealing healing, BarrowsTracker barrows, PartyManager party, PartyUpdates partyUpdates)
	{
		this.client = client;
		this.partyService = partyService;
		this.config = config;
		this.tracker = tracker;
		this.bosses = bosses;
		this.matcher = matcher;
		this.healing = healing;
		this.barrows = barrows;
		this.party = party;
		this.partyUpdates = partyUpdates;
	}

	void hitsplatApplied(Actor actor, Hitsplat hitsplat)
	{
		long now = System.currentTimeMillis();
		if (actor instanceof NPC)
		{
			npcHit((NPC) actor, hitsplat, now);
		}
		else if (actor == client.getLocalPlayer())
		{
			localPlayerHit(hitsplat, now);
		}
		else if (actor instanceof Player && config.estimateOthers() && isGroupMode())
		{
			otherPlayerHit((Player) actor, hitsplat, now);
		}
	}

	private void npcHit(NPC npc, Hitsplat hitsplat, long now)
	{
		int type = hitsplat.getHitsplatType();
		int amount = hitsplat.getAmount();
		String key = TargetMatcher.key(client.getWorld(), npc.getIndex());
		String name = Names.clean(npc.getName());
		boolean boss = bosses.isBoss(npc.getId(), name);
		WorldPoint pos = npc.getWorldLocation();
		if (pos != null)
		{
			matcher.seen(key, pos.getX(), pos.getY(), pos.getPlane());
		}

		if (hitsplat.isMine())
		{
			int tick = client.getTickCount();
			boolean miss = type == HitsplatID.BLOCK_ME || amount <= 0;
			String source = attackSource.sourceForHit(tick, healing.weaponName());
			// playerHit before seenHit, so the first hit of a fight is also seen
			tracker.playerHit(now, Names.localName(client), PlayerKind.LOCAL, key, npc.getId(), name, boss, amount, miss,
				source);
			tracker.seenHit(now, key, npc.getId(), name, boss, amount);
			barrows.hit(now, name);
			if (boss)
			{
				party.bossHit();
			}
			if (!miss)
			{
				healing.youHit(npc, amount, tick);
			}
			GoldenDpsUpdate.Hit sent = new GoldenDpsUpdate.Hit(npc.getIndex(), npc.getId(), name, amount, miss, boss, pos);
			sent.source = source;
			partyUpdates.addHit(sent);
		}
		else if (hitsplat.isOthers() && config.estimateOthers() && isGroupMode())
		{
			// party members send their own hits; without this setting other players are left out entirely
			tracker.seenHit(now, key, npc.getId(), name, boss, amount);
			String who = attributor.assign(client.getTickCount(), key);
			if (who != null && !party.isReporter(who, now) && !who.equals(Names.localName(client)))
			{
				tracker.estimateHit(now, who, key, amount, type == HitsplatID.BLOCK_OTHER || amount <= 0);
			}
		}
		else if (isEffect(type))
		{
			tracker.effectHit(now, key, npc.getId(), name, boss, amount);
		}
	}

	private void localPlayerHit(Hitsplat hitsplat, long now)
	{
		int amount = hitsplat.getAmount();
		if (amount <= 0 || !isDamageOnPlayer(hitsplat))
		{
			return;
		}
		healing.damageOnYou(amount);
		if (tracker.getCurrent() != null)
		{
			tracker.damageTaken(now, Names.localName(client), PlayerKind.LOCAL, amount);
			partyUpdates.addDamageTaken(amount);
		}
	}

	/** Damage on players without GoldenDPS, seen from your client. */
	private void otherPlayerHit(Player player, Hitsplat hitsplat, long now)
	{
		String who = Names.clean(player.getName());
		if (who != null && hitsplat.getAmount() > 0 && isDamageOnPlayer(hitsplat) && !party.isReporter(who, now))
		{
			tracker.seenDamageTaken(now, who, hitsplat.getAmount());
		}
	}

	void animationChanged(Actor actor)
	{
		if (actor == null)
		{
			return;
		}
		int animation = actor.getAnimation();
		Actor target = actor.getInteracting();
		if (animation == -1 || animation == EAT_ANIMATION || !(target instanceof NPC))
		{
			return;
		}
		if (actor == client.getLocalPlayer())
		{
			attackSource.attack(client.getTickCount(), healing.weaponName());
		}
		else if (actor instanceof Player && config.estimateOthers() && isGroupMode())
		{
			String who = Names.clean(actor.getName());
			if (who != null)
			{
				attributor.attack(client.getTickCount(), who, TargetMatcher.key(client.getWorld(), ((NPC) target).getIndex()));
			}
		}
	}

	/** A "Cast" menu click on a target, such as "Ice Barrage -> Vorkath". */
	void spellCastClicked(int tick, String target)
	{
		attackSource.castClicked(tick, target);
	}

	/** A drop in special attack energy means a special attack was used. */
	void tick(int tick)
	{
		int spec = client.getVarpValue(VarPlayerID.SA_ENERGY);
		if (lastSpecEnergy >= 0 && spec < lastSpecEnergy)
		{
			attackSource.specUsed(tick, healing.weaponName());
		}
		lastSpecEnergy = spec;
	}

	void reset()
	{
		attributor.clear();
		attackSource.reset();
		lastSpecEnergy = -1;
	}

	/**
	 * Other players count in an instance, and in a party while you fight a boss
	 * (or always in a party when "others only when together" is off).
	 */
	private boolean isGroupMode()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv != null && wv.isInstance())
		{
			return true;
		}
		if (!partyService.isInParty())
		{
			return false;
		}
		Fight current = tracker.getCurrent();
		return !config.othersOnlyTogether() || (current != null && current.hasBossTarget());
	}

	/** Damage over time; the game does not say who caused it. */
	private static boolean isEffect(int type)
	{
		return type == HitsplatID.POISON || type == HitsplatID.VENOM || type == HitsplatID.DISEASE
			|| type == HitsplatID.BURN || type == HitsplatID.BLEED;
	}

	private static boolean isDamageOnPlayer(Hitsplat hitsplat)
	{
		int type = hitsplat.getHitsplatType();
		return hitsplat.isMine() || hitsplat.isOthers() || isEffect(type) || type == HitsplatID.DOOM;
	}
}

package com.goldendps;

import static com.goldendps.PanelWidgets.GOLD;
import static com.goldendps.PanelWidgets.actionRow;
import static com.goldendps.PanelWidgets.bold;
import static com.goldendps.PanelWidgets.line;
import static com.goldendps.PanelWidgets.section;
import static com.goldendps.PanelWidgets.small;
import com.goldendps.model.BossRecords;
import com.goldendps.model.FightReport;
import com.goldendps.model.Format;
import com.goldendps.model.MonsterStats;
import com.goldendps.model.PlayerKind;
import com.goldendps.model.TargetDamage;
import java.awt.Color;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.JComponent;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/** The cards of the panel's fight details: the summary, one per player and one per target. Swing thread only. */
final class FightCards
{
	private FightCards()
	{
	}

	/** Only one player did damage: no group numbers, no shares. */
	/** A raid's bosses with their times and how each compares with its PB. */
	static JPanel bossTimes(List<String[]> bossTimes)
	{
		JPanel card = section();
		for (String[] boss : bossTimes)
		{
			String tag = boss[2];
			card.add(line(boss[0], boss[1] + (tag.isEmpty() ? "" : "  " + tag), tag.startsWith("NEW") ? GOLD : null));
		}
		return card;
	}

	static JPanel summary(GoldenDpsPanel.Data d)
	{
		FightReport r = d.report;
		JPanel card = section();
		card.add(bold(r.getTitle(), GOLD));
		card.add(line("Time", Format.duration(r.getDurationMs()) + (d.paused ? " (paused)" : d.running ? " (live)" : "")));
		if (d.fights > 0)
		{
			card.add(line("Fights", String.valueOf(d.fights)));
		}
		else
		{
			card.add(line("Started", new SimpleDateFormat("dd MMM HH:mm").format(new Date(d.startMs))));
		}
		boolean solo = r.isSolo();
		card.add(line(solo ? "Damage" : "Group damage", Format.amount(r.getTotalDamage())));
		card.add(line(solo ? "DPS" : "Group DPS", Format.dps(r.getGroupDps())));
		FightReport.PlayerRow topHit = r.topHit();
		if (topHit != null)
		{
			card.add(line("Max hit", topHit.biggestHit + (solo ? "" : " (" + topHit.name + ")")));
		}
		if (bossDiffers(d))
		{
			card.add(line("Boss time", Format.duration(d.bossReport.getDurationMs())));
			card.add(line("Boss damage", Format.amount(d.bossReport.getTotalDamage())));
			card.add(line("Boss DPS", Format.dps(d.bossReport.getGroupDps())));
		}
		for (String[] killLine : d.killLines)
		{
			String label = killLine[0];
			String value = killLine[1];
			card.add(line(label, value, value.contains("NEW") ? GOLD : null));
		}
		if (d.endReason != null && d.fights == 0)
		{
			card.add(line("Ended", d.endReason));
		}
		return card;
	}

	/** Boss lines only when they say something else than the fight lines (other targets were hit too). */
	private static boolean bossDiffers(GoldenDpsPanel.Data d)
	{
		return d.bossReport != null && (d.bossReport.getTotalDamage() != d.report.getTotalDamage()
			|| d.bossReport.getDurationMs() != d.report.getDurationMs());
	}

	/**
	 * In a solo fight the summary already has the damage and DPS.
	 * @param openSources weapons that show their accuracy, as {@link #sourceKey}
	 * @param toggleSource a click on a weapon opens or closes it
	 */
	static JPanel player(FightReport.PlayerRow row, FightReport.PlayerRow bossRow, boolean solo,
		Set<String> openSources, Consumer<String> toggleSource)
	{
		JPanel card = section();
		Color nameColor = row.kind == PlayerKind.LOCAL ? GOLD
			: row.kind == PlayerKind.PARTY ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR;
		String name = (row.isEstimate() ? "~" : "") + row.name
			+ (row.kind == PlayerKind.LOCAL ? " (you)" : row.isEstimate() ? " (guess)" : "");
		card.add(bold(name, nameColor));
		if (!solo)
		{
			card.add(line("Damage", Format.amount(row.damage) + "  (" + Format.percent(row.percent) + ")"));
			card.add(line("DPS", Format.dps(row.dps)));
		}
		if (!solo && bossRow != null && bossRow.damage > 0 && bossRow.damage != row.damage)
		{
			card.add(line("Boss damage", Format.amount(bossRow.damage) + "  (" + Format.percent(bossRow.percent) + ")"));
			card.add(line("Boss DPS", Format.dps(bossRow.dps)));
		}
		if (!row.isPlayer())
		{
			card.add(line("", row.kind == PlayerKind.UNKNOWN ? "Hits nobody could be matched to" : "Owner not known"));
			return card;
		}
		card.add(line("Biggest hit", String.valueOf(row.biggestHit)));
		card.add(line("Accuracy", Format.accuracy(row.hits, row.misses)));
		addSources(card, row.name, row.sources, "  ", openSources, toggleSource);
		if (row.isEstimate())
		{
			card.add(line("", "No GoldenDPS: damage is a guess"));
			card.add(line("Damage taken", Format.amount(row.damageTaken)));
			return card;
		}
		addHealing(card, row);
		card.add(line("Damage taken", Format.amount(row.damageTaken)));
		return card;
	}

	/**
	 * Damage per weapon, special attack or spell; a click shows its accuracy and biggest hit under it.
	 * @param owner the player or monster, so the same weapon opens on its own in every card
	 * @param indent spaces before the weapon names
	 */
	private static void addSources(JPanel card, String owner, List<FightReport.SourceRow> sources, String indent,
		Set<String> openSources, Consumer<String> toggleSource)
	{
		if (sources.isEmpty())
		{
			return;
		}
		card.add(line(indent.substring(2) + "Breakdown", ""));
		for (FightReport.SourceRow source : sources)
		{
			String key = sourceKey(owner, source.name);
			boolean open = openSources.contains(key);
			JComponent l = line(indent + (open ? "- " : "+ ") + source.name,
				Format.amount(source.damage) + "  (" + Format.percent(source.percent) + ")");
			l.setToolTipText(String.format("%s: %d hits, %d misses, biggest %d, average %.1f per attack. Click for accuracy.",
				source.name, source.hits, source.misses, source.biggestHit, source.average()));
			PanelWidgets.clickable(l, () -> toggleSource.accept(key));
			card.add(l);
			if (open)
			{
				card.add(line(indent + "    Accuracy", Format.accuracy(source.hits, source.misses)));
				card.add(line(indent + "    Biggest hit", String.valueOf(source.biggestHit)));
			}
		}
	}

	/** One weapon in one card, so the same weapon of two players opens on its own. */
	static String sourceKey(String owner, String source)
	{
		return owner + "|" + source;
	}

	/** The list line of a monster: "143 kills  90%". */
	static String monsterSummary(MonsterStats.Entry e)
	{
		MonsterStats.Monster m = e.stats;
		String accuracy = m == null || m.attacks.hits + m.attacks.misses == 0 ? ""
			: "  " + Format.percent(100.0 * m.attacks.hits / (m.attacks.hits + m.attacks.misses));
		return e.kills() + (e.kills() == 1 ? " kill" : " kills") + accuracy;
	}

	/** The open card of a monster, raid or Barrows run: personal bests, then your stats over all kills. */
	static void addMonster(JPanel card, MonsterStats.Entry e, Set<String> openSources, Consumer<String> toggleSource,
		Runnable reset)
	{
		MonsterStats.Monster m = e.stats;
		card.add(actionRow(small("  Personal bests and stats", ColorScheme.LIGHT_GRAY_COLOR), "reset",
			"Delete the personal bests and stats of " + e.name, reset));
		addBest(card, "Solo", e.solo);
		addBest(card, "Party", e.party);
		if (m == null)
		{
			return;
		}
		if (e.solo == null && e.party == null && m.fastestMs > 0)
		{
			card.add(line("  Best time", Format.duration(m.fastestMs)));
		}
		if (m.averageMs() > 0)
		{
			card.add(line("  Average time", Format.duration(m.averageMs())));
		}
		card.add(line("  Biggest hit", String.valueOf(m.attacks.biggestHit)));
		card.add(line("  Damage per kill", Format.amount(m.attacks.damage / m.kills)));
		card.add(line("  Accuracy", Format.accuracy(m.attacks.hits, m.attacks.misses)));
		addSources(card, e.name, FightReport.sourceRows(m.weapons, m.attacks.damage), "    ", openSources,
			toggleSource);
	}

	/** "Solo PB  1:21 (5.2 DPS)"; a boss on a fixed timer has most damage instead of a time. */
	private static void addBest(JPanel card, String label, BossRecords.Record rec)
	{
		if (rec == null)
		{
			return;
		}
		String best = BossRecords.isTimed(rec.boss) ? Format.amount(rec.mostDamage) + " damage"
			: Format.duration(rec.fastestMs);
		card.add(line("  " + label + " PB", best + (rec.bestDps > 0 ? "  (" + Format.dps(rec.bestDps) + " DPS)" : "")));
	}

	private static void addHealing(JPanel card, FightReport.PlayerRow row)
	{
		card.add(line("Healing", Format.amount(row.healing)));
		addIfAny(card, "  Food/potions", row.healFood);
		addIfAny(card, "  Lifesteal", row.healLifesteal);
		addIfAny(card, "  On others", row.healOther);
		if (row.overheal > 0)
		{
			card.add(line("Overhealing", Format.percent(row.overhealPercent()) + "  (" + Format.amount(row.overheal) + ")"));
		}
	}

	private static void addIfAny(JPanel card, String label, long amount)
	{
		if (amount > 0)
		{
			card.add(line(label, Format.amount(amount)));
		}
	}

	static JPanel target(FightReport.TargetRow target)
	{
		JPanel card = section();
		String tags = (target.boss ? " [boss]" : "") + (target.died ? " [dead]" : "");
		card.add(bold(target.name + tags, Color.WHITE));
		card.add(line("Total", Format.amount(target.total)));
		for (Map.Entry<String, Long> byPlayer : target.byPlayer.entrySet())
		{
			double percent = target.total == 0 ? 0 : 100.0 * byPlayer.getValue() / target.total;
			card.add(line("  " + byPlayer.getKey(), Format.amount(byPlayer.getValue()) + " (" + Format.percent(percent) + ")"));
			TargetDamage attacks = target.attacksByPlayer.get(byPlayer.getKey());
			if (attacks != null)
			{
				card.add(line("    Accuracy", Format.accuracy(attacks.hits, attacks.misses)));
			}
		}
		return card;
	}
}

package com.goldendps;

import com.goldendps.model.BossRecords;
import com.goldendps.model.Fight;
import com.goldendps.model.FightTracker;
import com.goldendps.model.HistoryStore;
import com.goldendps.model.MonsterStats;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Future;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;

/**
 * Loads and saves the fight history, personal bests and monster stats of the logged-in account.
 * State is changed on the client thread; files are written on the executor from copies.
 */
@Slf4j
class FightStorage
{
	private static final long SAVE_EVERY_MS = 30_000;

	private final FightTracker tracker;
	private final HistoryStore store;
	private final ExecutorService executor;
	private final ClientThread clientThread;
	private final Runnable onLoaded;

	private long account = -1;
	private boolean dirty;
	private long lastSaveMs;
	private BossRecords records = new BossRecords();
	private MonsterStats monsters = new MonsterStats();
	/** Personal bests and monster stats are loaded. */
	private boolean statsLoaded;
	/** Fights that ended and monsters that died while the stats were loading. */
	private final List<Runnable> pendingStats = new ArrayList<>();
	private final Map<String, BossRecords.Compare> killCompares = new HashMap<>();

	FightStorage(FightTracker tracker, HistoryStore store, ExecutorService executor, ClientThread clientThread,
		Runnable onLoaded)
	{
		this.tracker = tracker;
		this.store = store;
		this.executor = executor;
		this.clientThread = clientThread;
		this.onLoaded = onLoaded;
	}

	/** Switches to this account and loads its data (once per account). */
	void loadAccount(long hash)
	{
		if (hash == -1 || hash == account)
		{
			return;
		}
		if (account != -1)
		{
			save();
		}
		tracker.endNow(System.currentTimeMillis(), "Account changed");
		tracker.clearHistory();
		account = hash;
		records = new BossRecords();
		monsters = new MonsterStats();
		statsLoaded = false;
		pendingStats.clear();
		killCompares.clear();
		executor.execute(() ->
		{
			try
			{
				List<Fight> loaded = store.load(hash);
				BossRecords saved = store.loadRecords(hash);
				MonsterStats savedMonsters = store.loadMonsters(hash);
				clientThread.invokeLater(() -> loaded(hash, loaded, saved, savedMonsters));
			}
			catch (Exception ex)
			{
				log.warn("Could not load fight history", ex);
			}
		});
	}

	private void loaded(long hash, List<Fight> loaded, BossRecords saved, MonsterStats savedMonsters)
	{
		if (account != hash)
		{
			return;
		}
		if (saved == null)
		{
			saved = new BossRecords();
			saved.seed(loaded);
		}
		records = saved;
		monsters = savedMonsters;
		statsLoaded = true;
		pendingStats.forEach(Runnable::run);
		pendingStats.clear();
		saveStats();

		// fights that ended while loading are newer than the loaded ones
		List<Fight> all = new ArrayList<>(tracker.getHistory());
		all.addAll(loaded);
		tracker.setHistory(all);
		onLoaded.run();
	}

	void unload()
	{
		account = -1;
	}

	void fightEnded(Fight fight)
	{
		dirty = true;
		save();
		if (account == -1)
		{
			return;
		}
		addToStats(() -> addRecord(fight));
	}

	/** A monster died in this fight: it shows in the monster stats right away. */
	void monsterDied(Fight fight, String targetKey)
	{
		if (account != -1)
		{
			addToStats(() -> monsters.addKill(fight, targetKey));
		}
	}

	/** Runs now, or after loading when the stats are not loaded yet; then saves them. */
	private void addToStats(Runnable change)
	{
		if (!statsLoaded)
		{
			pendingStats.add(change);
			return;
		}
		change.run();
		saveStats();
	}

	private void addRecord(Fight fight)
	{
		BossRecords.Kill kill = BossRecords.record(fight);
		if (kill != null)
		{
			kill.fightId = fight.id;
			killCompares.put(fight.id, records.add(kill));
		}
	}

	/** Saves a running fight now and then, so a crash loses little. */
	void tick(long now)
	{
		if (tracker.getCurrent() != null)
		{
			dirty = true;
		}
		if (dirty && now - lastSaveMs >= SAVE_EVERY_MS)
		{
			save();
		}
	}

	void save()
	{
		if (account == -1)
		{
			return;
		}
		long acc = account;
		List<Fight> snapshot = snapshot();
		dirty = false;
		lastSaveMs = System.currentTimeMillis();
		executor.execute(() -> write(acc, snapshot));
	}

	/** Final save on client shutdown; returns the write to wait for, or null. */
	Future<?> saveNow()
	{
		if (account == -1)
		{
			return null;
		}
		long acc = account;
		List<Fight> snapshot = snapshot();
		return executor.submit(() -> write(acc, snapshot));
	}

	BossRecords.Record record(String boss, boolean party)
	{
		return records.get(boss, party);
	}

	BossRecords.Compare compare(String fightId)
	{
		return killCompares.get(fightId);
	}

	/** Every monster, raid and Barrows run with its stats and personal bests, last kill first. */
	List<MonsterStats.Entry> monsterEntries()
	{
		return monsters.entries(records.list());
	}

	/** Deletes the stats and personal bests of one monster, raid or Barrows run. */
	void resetMonster(String name)
	{
		monsters.remove(name);
		records.remove(name, false);
		records.remove(name, true);
		saveStats();
	}

	/** Deletes the stats and personal bests of everything. */
	void resetAllMonsters()
	{
		monsters = new MonsterStats();
		records = new BossRecords();
		killCompares.clear();
		saveStats();
	}

	private void saveStats()
	{
		if (account == -1 || !statsLoaded)
		{
			return;
		}
		long acc = account;
		BossRecords recordsCopy = records.copy();
		MonsterStats monstersCopy = monsters.copy();
		executor.execute(() ->
		{
			try
			{
				store.saveRecords(acc, recordsCopy);
				store.saveMonsters(acc, monstersCopy);
			}
			catch (Exception ex)
			{
				log.warn("Could not save personal bests and monster stats", ex);
			}
		});
	}

	private List<Fight> snapshot()
	{
		List<Fight> out = new ArrayList<>();
		Fight current = tracker.getCurrent();
		if (current != null && current.knownDamage() > 0)
		{
			Fight unfinished = current.copy();
			unfinished.endMs = Math.max(unfinished.startMs, unfinished.lastActivityMs);
			unfinished.endReason = "Not finished (saved)";
			out.add(unfinished);
		}
		for (Fight f : tracker.getHistory())
		{
			out.add(f.copy());
		}
		return out;
	}

	private void write(long acc, List<Fight> fights)
	{
		try
		{
			store.save(acc, fights, System.currentTimeMillis());
		}
		catch (Exception ex)
		{
			log.warn("Could not save fight history", ex);
		}
	}
}

package com.goldendps;

import com.goldendps.model.FightReport;
import com.goldendps.model.Format;
import com.goldendps.model.HungryTalk;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;

/**
 * The fun extras for group fights: a crown over the MVP, a burger over the top healer of the
 * whole fight (or raid), fries over the top healer on the current boss, and lines from both.
 * Updated on the client thread, read by the overlays.
 */
class FunEffects
{
	/** Icons stay this long after the fight ended. */
	private static final long SHOW_AFTER_FIGHT_MS = 30_000;
	private static final long SAY_MS = 5000;

	/** Something a player "says" over their head for a while (drawn by the overlay only). */
	private static final class Speech
	{
		final String text;
		final long until;

		Speech(String text, long until)
		{
			this.text = text;
			this.until = until;
		}
	}

	private final HungryTalk burgerTalk = new HungryTalk(new Random());
	private final HungryTalk friesTalk = new HungryTalk(new Random());

	private String mvp;
	private String burger;
	private String fries;
	private final Map<String, Speech> speech = new HashMap<>();
	private String lastBossFightId;

	/**
	 * @param fight  the running or last fight (the whole raid inside a raid), or null
	 * @param boss   the current or last boss fight, or null
	 * @param bossId id of that boss fight, to announce its healer once
	 */
	void update(FightReport fight, long fightEndedMs, FightReport boss, long bossEndedMs, String bossId, long now)
	{
		FightReport shownFight = visible(fight, fightEndedMs, now) ? fight : null;
		FightReport shownBoss = visible(boss, bossEndedMs, now) ? boss : null;
		mvp = name(shownFight == null ? null : shownFight.topDamage());
		FightReport.PlayerRow fightHealer = shownFight == null ? null : shownFight.topHealer();
		FightReport.PlayerRow bossHealer = shownBoss == null ? null : shownBoss.topHealer();
		burger = name(fightHealer);
		fries = name(bossHealer);
		if (bossHealer != null && bossEndedMs > 0 && !bossId.equals(lastBossFightId))
		{
			lastBossFightId = bossId;
			announceHealers(bossHealer, fightHealer, now);
		}
		speech.values().removeIf(s -> now >= s.until);
	}

	/** After a boss kill the fries holder says the boss heal and the burger holder the total. */
	private void announceHealers(FightReport.PlayerRow bossHealer, FightReport.PlayerRow fightHealer, long now)
	{
		boolean samePlayer = fightHealer == null || fightHealer.name.equals(bossHealer.name);
		if (samePlayer)
		{
			long total = fightHealer == null ? bossHealer.healing : fightHealer.healing;
			say(bossHealer.name, healedLine(bossHealer.healing, total), now);
			return;
		}
		say(bossHealer.name, healedLine(bossHealer.healing, bossHealer.healing), now);
		say(fightHealer.name, "Total healed: " + Format.amount(fightHealer.healing) + " HP!", now);
	}

	/** "I healed 1,234 HP!", with the total when the whole fight healed more. */
	private static String healedLine(long boss, long total)
	{
		String line = "I healed " + Format.amount(boss) + " HP!";
		return total > boss ? line + " (" + Format.amount(total) + " total)" : line;
	}

	private void say(String player, String text, long now)
	{
		speech.put(player, new Speech(text, now + SAY_MS));
	}

	private static boolean visible(FightReport report, long endedMs, long now)
	{
		return report != null && report.playerCount() >= 2 && (endedMs == 0 || now - endedMs < SHOW_AFTER_FIGHT_MS);
	}

	private static String name(FightReport.PlayerRow row)
	{
		return row == null ? null : row.name;
	}

	boolean hasCrown(String player)
	{
		return player.equals(mvp);
	}

	boolean hasBurger(String player)
	{
		return player.equals(burger);
	}

	boolean hasFries(String player)
	{
		return player.equals(fries);
	}

	boolean anyone()
	{
		return mvp != null || burger != null || fries != null || !speech.isEmpty();
	}

	/** What the player says now: the heal after a boss first, otherwise a hungry line. Null when silent. */
	String line(String player, long now)
	{
		Speech s = speech.get(player);
		if (s != null && now < s.until)
		{
			return s.text;
		}
		return hungryLine(player, now);
	}

	private String hungryLine(String player, long now)
	{
		if (hasBurger(player))
		{
			return burgerTalk.line(now);
		}
		return hasFries(player) ? friesTalk.line(now) : null;
	}
}

package com.goldendps;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/** Small icons drawn in code, so the plugin needs no extra image files. */
final class FunIcons
{
	static final BufferedImage CROWN = crown();
	static final BufferedImage BURGER = burger();
	static final BufferedImage FRIES = fries();

	private static final Color OUTLINE = new Color(40, 25, 10);

	private FunIcons()
	{
	}

	private static Graphics2D canvas(BufferedImage img)
	{
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setStroke(new BasicStroke(1.2f));
		return g;
	}

	private static BufferedImage crown()
	{
		BufferedImage img = new BufferedImage(22, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas(img);
		Polygon p = new Polygon(new int[]{2, 2, 6, 11, 16, 20, 20}, new int[]{14, 4, 9, 2, 9, 4, 14}, 7);
		g.setColor(new Color(255, 196, 0));
		g.fillPolygon(p);
		g.setColor(OUTLINE);
		g.drawPolygon(p);
		g.setColor(new Color(220, 40, 60));
		g.fillOval(9, 9, 4, 4);
		g.setColor(new Color(60, 140, 255));
		g.fillOval(4, 10, 3, 3);
		g.fillOval(15, 10, 3, 3);
		g.dispose();
		return img;
	}

	private static BufferedImage burger()
	{
		BufferedImage img = new BufferedImage(20, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas(img);
		g.setColor(new Color(225, 150, 60));
		g.fillArc(1, 1, 18, 11, 0, 180);
		g.setColor(new Color(90, 190, 60));
		g.fillRect(1, 7, 18, 2);
		g.setColor(new Color(110, 60, 30));
		g.fillRoundRect(1, 9, 18, 3, 2, 2);
		g.setColor(new Color(225, 150, 60));
		g.fillRoundRect(2, 12, 16, 3, 3, 3);
		g.setColor(OUTLINE);
		g.drawArc(1, 1, 18, 11, 0, 180);
		g.drawRoundRect(2, 12, 16, 3, 3, 3);
		g.setColor(new Color(255, 240, 200));
		g.fillRect(6, 3, 1, 1);
		g.fillRect(11, 2, 1, 1);
		g.fillRect(14, 4, 1, 1);
		g.dispose();
		return img;
	}

	private static BufferedImage fries()
	{
		BufferedImage img = new BufferedImage(16, 20, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas(img);
		g.setColor(new Color(250, 210, 70));
		for (int x = 3; x <= 11; x += 2)
		{
			g.fillRect(x, 1 + (x % 3), 2, 10);
		}
		Polygon box = new Polygon(new int[]{1, 15, 13, 3}, new int[]{8, 8, 19, 19}, 4);
		g.setColor(new Color(210, 40, 40));
		g.fillPolygon(box);
		g.setColor(OUTLINE);
		g.drawPolygon(box);
		g.setColor(new Color(255, 196, 0));
		g.fillOval(6, 11, 4, 4);
		g.dispose();
		return img;
	}
}

