	{
		BarrowsRun run = new BarrowsRun();
		run.hit(0, DHAROK);
		run.loggedOut(3 * MIN);
		run.hit(61 * MIN, VERAC);      // an hour away: the clock starts again at the next brother hit
		assertEquals("3 minutes before logout, 2 from the next hit", 5 * MIN, run.chestOpened(63 * MIN).activeMs);
	}

	@Test
	public void theClockStopsTenMinutesAfterTheLastBrotherHit()
	{
		BarrowsRun run = new BarrowsRun();
		run.hit(0, DHAROK);
		run.hit(30 * MIN, VERAC);      // 30 minutes AFK: only 10 count
		assertEquals(10 * MIN + 2 * MIN, run.chestOpened(32 * MIN).activeMs);
	}

	@Test
	public void theLiveTimeStopsWhenIdle()
	{
		BarrowsRun run = new BarrowsRun();
		run.hit(0, DHAROK);
		assertEquals(5 * MIN, run.activeMs(5 * MIN));
		assertFalse(run.isPaused(5 * MIN));
		assertEquals(10 * MIN, run.activeMs(15 * MIN));
		assertTrue(run.isPaused(15 * MIN));
	}

	@Test
	public void aSavedRunGoesOnAfterARestart()
	{
		BarrowsRun run = new BarrowsRun();
		assertTrue("the first brother hit starts a run", run.hit(0, DHAROK));
		assertFalse(run.hit(MIN, DHAROK));
		run.died(DHAROK);
		BarrowsRun.Saved saved = run.save(4 * MIN);    // then the client crashes

		BarrowsRun after = new BarrowsRun();
		after.restore(saved);
		assertTrue(after.isRunning());
		assertTrue("stopped until the next brother hit", after.isPaused(30 * MIN));
		assertEquals(4 * MIN, after.activeMs(30 * MIN));
		after.hit(31 * MIN, VERAC);
		assertEquals(4 * MIN + MIN, after.chestOpened(32 * MIN).activeMs);

		BarrowsRun again = new BarrowsRun();
		again.restore(saved);
		assertTrue("a killed brother is remembered: hitting him starts a new run", again.hit(40 * MIN, DHAROK));
		assertNull("no saved run after the chest", after.save(33 * MIN));
	}

	@Test
	public void theRunCountsOnlyDamageOnTheBrothers()
	{
		FightTracker t = new FightTracker();
		BarrowsRun run = new BarrowsRun();
		hit(t, run, 10_000, "1:1", DHAROK, true);
		hit(t, run, 12_000, "1:9", RAT, false);   // a rat in the brother fight
		kill(t, run, 40_000, "1:1", DHAROK, true);
		// tunnel and bank: 5 minutes without brother hits
		hit(t, run, 200_000, "1:2", RAT, false);
		kill(t, run, 205_000, "1:2", RAT, false);
		hit(t, run, 340_000, "1:3", VERAC, true);
		kill(t, run, 370_000, "1:3", VERAC, true);

		Fight r = addRun(t, run.chestOpened(380_000));
		assertEquals(BarrowsRun.NAME, r.title());
		assertEquals("first brother hit to chest, banking included", 370_000, r.durationMs(380_000));
		assertEquals("brothers only", 60, FightReport.of(r, false, 380_000).total(MeterMode.DAMAGE), 0.001);
		assertTrue(r.isCompleteRaid());
		assertFalse("no boss meter for the run", r.hasBossMeter());
		assertEquals("the session total counts every fight once", 120,
			FightReport.of(t.getSessionTotal(380_000), false, 380_000).total(MeterMode.DAMAGE), 0.001);

		assertNull("two brothers is no full run: no personal best", BossRecords.record(r));
		assertNull("no boss report for the run", BossRecords.kill(r));

		List<KillRates.Rate> rates = KillRates.of(t.getSessionFights(), 380_000);
		assertEquals(1, rates.stream().filter(x -> x.kind == KillRates.Kind.RUN && x.kills == 1).count());
		assertEquals("brothers are in chests per hour, not in bosses", 0,
			rates.stream().filter(x -> x.kind == KillRates.Kind.BOSS).count());
		assertEquals("the dead rat is counted once", 1, rates.stream()
			.filter(x -> x.kind == KillRates.Kind.MONSTER).mapToInt(x -> x.kills).sum());
	}

	@Test
	public void aBrotherInAFightThatStartedWithARatCounts()
	{
		FightTracker t = new FightTracker();
		BarrowsRun run = new BarrowsRun();
		hit(t, run, 1000, "1:9", RAT, false);
		kill(t, run, 3000, "1:9", RAT, false);
		hit(t, run, 10_000, "1:1", DHAROK, true);
		kill(t, run, 20_000, "1:1", DHAROK, true);
		Fight r = addRun(t, run.chestOpened(30_000));
		assertEquals(30, FightReport.of(r, false, 30_000).total(MeterMode.DAMAGE), 0.001);
	}

	@Test
	public void brothersWithTheSameNpcIndexStayApart()
	{
		FightTracker t = new FightTracker();
		BarrowsRun run = new BarrowsRun();
		hit(t, run, 1000, "1:5", DHAROK, true);
		kill(t, run, 2000, "1:5", DHAROK, true);
		hit(t, run, 60_000, "1:5", VERAC, true);
		kill(t, run, 61_000, "1:5", VERAC, true);
		Fight r = addRun(t, run.chestOpened(70_000));
		assertEquals(2, r.targets.size());
		assertEquals(2, FightReport.of(r, false, 70_000).getTargets().size());
	}

	@Test
	public void onlyAFullRunSetsAPersonalBest()
	{
		String[] brothers = {"Ahrim the Blighted", DHAROK, "Guthan the Infested", "Karil the Tainted",
			"Torag the Corrupted", VERAC};
		FightTracker t = new FightTracker();
		BarrowsRun run = new BarrowsRun();
		for (int i = 0; i < brothers.length; i++)
		{
			hit(t, run, MIN * i, "1:" + i, brothers[i], true);
			kill(t, run, MIN * i + 20_000, "1:" + i, brothers[i], true);
		}
		Fight r = addRun(t, run.chestOpened(6 * MIN));
		assertTrue(BarrowsRun.isFullRun(r));
		BossRecords.Kill record = BossRecords.record(r);
		assertEquals(BarrowsRun.NAME, record.boss);
		assertEquals(6 * MIN, record.timeMs);
	}

	@Test
	public void idleTimeIsLeftOutOfTheRunTime()
	{
		FightTracker t = new FightTracker();
		BarrowsRun run = new BarrowsRun();
		hit(t, run, 0, "1:1", DHAROK, true);
		kill(t, run, MIN, "1:1", DHAROK, true);
		hit(t, run, 40 * MIN, "1:3", VERAC, true);
		kill(t, run, 41 * MIN, "1:3", VERAC, true);
		Fight r = addRun(t, run.chestOpened(42 * MIN));
		assertEquals("10 idle minutes count, then from the next hit", 12 * MIN, r.durationMs(42 * MIN));
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class BossRecordsTest
{
	private static final double D = 0.001;
	private static final String BOSS = "301:5";

	/** A Vorkath kill: I hit every 5 s for 'hit' damage, boss dies at 1000 + seconds*1000. */
	private static Fight vorkath(int seconds, int hit)
	{
		FightTracker t = new FightTracker();
		long t0 = 1000;
		for (int s = 0; s < seconds; s += 5)
		{
			t.playerHit(t0 + s * 1000L, "Me", PlayerKind.LOCAL, BOSS, 1, "Vorkath", true, hit, false);
		}
		t.npcDied(t0 + seconds * 1000L, BOSS, true);
		return t.getHistory().get(0);
	}

	@Test
	public void killIsWorkedOutFromTheFight()
	{
		BossRecords.Kill k = BossRecords.kill(vorkath(60, 50));
		assertNotNull(k);
		assertEquals("Vorkath", k.boss);
		assertEquals(60_000, k.timeMs);
		assertEquals(12 * 50 / 60.0, k.myDps, D);
	}

	@Test
	public void soloAndPartyKillsHaveTheirOwnRecords()
	{
		FightTracker t = new FightTracker();
		for (int s = 0; s < 30; s += 5)
		{
			t.playerHit(1000 + s * 1000L, "Me", PlayerKind.LOCAL, BOSS, 1, "Vorkath", true, 50, false);
			t.playerHit(1000 + s * 1000L, "Friend", PlayerKind.PARTY, BOSS, 1, "Vorkath", true, 50, false);
		}
		t.npcDied(31_000, BOSS, true);
		BossRecords.Kill duo = BossRecords.kill(t.getHistory().get(0));
		assertTrue(duo.party);
		assertFalse(BossRecords.kill(vorkath(60, 50)).party);

		BossRecords r = new BossRecords();
		r.add(BossRecords.kill(vorkath(60, 50)));
		BossRecords.Compare c = r.add(duo);
		assertNull("the first party kill is compared with nothing", c.before);
		assertEquals(60_000, r.get("Vorkath", false).fastestMs);
		assertEquals(30_000, r.get("Vorkath", true).fastestMs);
		assertEquals("Vorkath (party)", r.get("Vorkath", true).label());
		assertEquals("Vorkath (solo)", r.get("Vorkath", false).label());
	}

	@Test
	public void paceSpreadsTheTimeOverTheHealthThatIsGone()
	{
		BossRecords.Record pb = new BossRecords.Record();
		pb.fastestMs = 60_000;
		assertEquals("half dead after 25 s: heading for 50 s", -10_000L, (long) BossRecords.paceMs(25_000, 0.5, pb));
		assertEquals(15_000L, (long) BossRecords.paceMs(30_000, 0.4, pb));
		assertNull("too early to tell", BossRecords.paceMs(2_000, 0.05, pb));
		assertNull("no PB yet", BossRecords.paceMs(25_000, 0.5, null));
		assertEquals("-0:10", BossRecords.paceText(-10_000));
		assertEquals("+0:15", BossRecords.paceText(15_000));
	}

	private static BossRecords.Kill crab(int damage)
	{
		FightTracker t = new FightTracker();
		t.playerHit(1000, "Me", PlayerKind.LOCAL, BOSS, 1, "Gemstone Crab", true, damage, false);
		t.npcDied(600_000, BOSS, true);
		return BossRecords.kill(t.getHistory().get(0));
	}

	@Test
	public void theGemstoneCrabPbIsYourMostDamage()
	{
		BossRecords r = new BossRecords();
		r.add(crab(500));
		BossRecords.Compare less = r.add(crab(300));
		assertEquals("PB 500", BossRecords.meterTag(null, less));
		BossRecords.Compare more = r.add(crab(800));
		assertEquals("NEW PB!", BossRecords.meterTag(null, more));
		assertEquals(800, r.get("Gemstone Crab", false).mostDamage);
		assertEquals("no fastest time on a timer", 0, r.get("Gemstone Crab", false).fastestMs);
	}

	@Test
	public void aRecordCanBeRemoved()
	{
		BossRecords r = new BossRecords();
		r.add(BossRecords.kill(vorkath(60, 50)));
		r.remove("Vorkath", false);
		assertNull(r.get("Vorkath", false));
		assertTrue(r.list().isEmpty());
	}

	@Test
	public void noKillWithoutABossDeath()
	{
		FightTracker t = new FightTracker();
		t.playerHit(1000, "Me", PlayerKind.LOCAL, BOSS, 1, "Vorkath", true, 50, false);
		t.endNow(5000, "test");
		assertNull(BossRecords.kill(t.getHistory().get(0)));
		assertNull(BossRecords.kill(null));
	}

	@Test
	public void firstKillIsAPbAndLaterKillsCompare()
	{
		BossRecords r = new BossRecords();
		BossRecords.Compare first = r.add(BossRecords.kill(vorkath(60, 50)));
		assertNull(first.before);
		assertTrue(first.newFastest);
		assertTrue(first.newBestDps);

		// slower kill, less DPS
		BossRecords.Compare slower = r.add(BossRecords.kill(vorkath(70, 40)));
		assertFalse(slower.newFastest);
		assertFalse(slower.newBestDps);
		assertEquals(60_000, slower.before.fastestMs);
		assertTrue(slower.vsLastDpsPercent() < 0);

		// faster kill with more DPS
		BossRecords.Compare faster = r.add(BossRecords.kill(vorkath(50, 80)));
		assertTrue(faster.newFastest);
		assertTrue(faster.newBestDps);
		BossRecords.Record rec = r.get("Vorkath", false);
		assertEquals(3, rec.kills);
		assertEquals(50_000, rec.fastestMs);
	}

	@Test
	public void vsLastKillPercent()
	{
		BossRecords r = new BossRecords();
		r.add(BossRecords.kill(vorkath(60, 50)));   // 10 DPS
		BossRecords.Compare c = r.add(BossRecords.kill(vorkath(60, 55))); // 11 DPS
		assertEquals(10.0, c.vsLastDpsPercent(), D);
	}

	@Test
	public void seedFromSavedFights()
	{
		List<Fight> newestFirst = Arrays.asList(vorkath(50, 80), vorkath(60, 50));
		BossRecords r = new BossRecords();
		r.seed(newestFirst);
		BossRecords.Record rec = r.get("Vorkath", false);
		assertEquals(2, rec.kills);
		assertEquals(50_000, rec.fastestMs);
		// the newest kill is the last one
		assertEquals(80 * 10 / 50.0, rec.lastDps, D);
		assertEquals(Collections.singletonList("Vorkath"), Collections.singletonList(r.list().get(0).boss));
	}

	@Test
	public void survivesJsonAndCopyIsDeep()
	{
		BossRecords r = new BossRecords();
		r.add(BossRecords.kill(vorkath(60, 50)));
		BossRecords back = new Gson().fromJson(new Gson().toJson(r), BossRecords.class);
		assertEquals(60_000, back.get("Vorkath", false).fastestMs);

		BossRecords c = r.copy();
		r.add(BossRecords.kill(vorkath(40, 50)));
		assertEquals(60_000, c.get("Vorkath", false).fastestMs);
	}

	@Test
	public void textForMeterAndPanel()
	{
		BossRecords r = new BossRecords();
		BossRecords.Compare first = r.add(BossRecords.kill(vorkath(60, 50)));
		assertNull("no PB tag on the first kill", BossRecords.meterTag(r.get("Vorkath", false), first));
		assertEquals("first kill!", BossRecords.killLines(first).get(0)[1].replace("1:00 (", "").replace(")", ""));

		assertEquals("PB 1:00", BossRecords.meterTag(r.get("Vorkath", false), null));

		BossRecords.Compare slow = r.add(BossRecords.kill(vorkath(70, 40)));
		assertEquals("PB 1:00", BossRecords.meterTag(r.get("Vorkath", false), slow));
		assertEquals("1:10 (PB 1:00)", BossRecords.killLines(slow).get(0)[1]);

		BossRecords.Compare fast = r.add(BossRecords.kill(vorkath(50, 80)));
		assertEquals("NEW PB!", BossRecords.meterTag(r.get("Vorkath", false), fast));
		List<String[]> lines = BossRecords.killLines(fast);
		assertEquals("0:50 NEW PB! (was 1:00)", lines.get(0)[1]);
		assertTrue(lines.get(1)[1].contains("NEW BEST ("));
		assertEquals("vs last kill", lines.get(2)[0]);
		assertTrue(lines.get(2)[1].startsWith("+"));
		assertEquals("3", lines.get(3)[1]);
		assertTrue(BossRecords.killLines(null).isEmpty());
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

public class FightTrackerTest
{
	private static final double D = 0.001;
	private static final String BOSS = "301:10";
	private static final String RAT = "301:20";

	private FightTracker tracker;
	private final List<Fight> ended = new ArrayList<>();

	@Before
	public void setUp()
	{
		tracker = new FightTracker();
		tracker.setIdleTimeoutMs(10_000);
		tracker.setListener(ended::add);
	}

	/** A hit by me, called in the same order as the plugin does it. */
	private void myHit(long t, String key, boolean boss, int amount)
	{
		String name = boss ? "Vorkath" : "Rat";
		tracker.playerHit(t, "Me", PlayerKind.LOCAL, key, 1, name, boss, amount, amount == 0);
		tracker.seenHit(t, key, 1, name, boss, amount);
	}

	private void partyHit(long t, String who, String key, boolean boss, int amount, boolean alsoSeen)
	{
		String name = boss ? "Vorkath" : "Rat";
		tracker.playerHit(t, who, PlayerKind.PARTY, key, 1, name, boss, amount, amount == 0);
		if (alsoSeen)
		{
			tracker.seenHit(t, key, 1, name, boss, amount);
		}
	}

	private FightReport report(Fight f, long now)
	{
		return FightReport.of(f, false, now);
	}

	@Test
	public void theOverallMeterGoesOnOverBossKills()
	{
		myHit(1000, BOSS, true, 50);
		tracker.npcDied(2000, BOSS, true);
		assertTrue(tracker.isOverallGoingOn(5000));
		myHit(6000, "301:11", true, 30);
		assertEquals("both kills", 80, report(tracker.getOverall(7000), 7000).getTotalDamage());
		tracker.npcDied(7000, "301:11", true);

		// a break longer than the idle time starts the overall meter again
		assertFalse(tracker.isOverallGoingOn(7000 + 10_001));
		myHit(30_000, BOSS, true, 20);
		assertEquals(20, report(tracker.getOverall(31_000), 31_000).getTotalDamage());
	}

	@Test
	public void soloDamageDpsAndAccuracy()
	{
		myHit(0, RAT, false, 10);
		myHit(2400, RAT, false, 0);
		myHit(4800, RAT, false, 20);
		myHit(10_000, RAT, false, 30);

		FightReport r = report(tracker.getCurrent(), 10_000);
		FightReport.PlayerRow me = r.row("Me");
		assertEquals(60, me.damage);
		assertEquals(3, me.hits);
		assertEquals(1, me.misses);
		assertEquals(30, me.biggestHit);
		assertEquals("75% (3/4)", Format.accuracy(me.hits, me.misses));
		assertEquals("-", Format.accuracy(0, 0));
		TargetDamage onTarget = r.getTargets().get(0).attacksByPlayer.get("Me");
		assertEquals(3, onTarget.hits);
		assertEquals(1, onTarget.misses);
		assertEquals(6.0, me.dps, D);
		assertEquals(100.0, me.percent, D);
		assertNull("solo: no unknown row", r.row(FightReport.UNKNOWN_NAME));
		assertEquals(PlayerKind.LOCAL, me.kind);
	}

	@Test
	public void partyDamageAndOthersUnknown()
	{
		myHit(0, BOSS, true, 30);
		// party member hit: I see the hitsplat and get the report
		partyHit(600, "Friend", BOSS, true, 20, true);
		// someone without the plugin: I only see the hitsplat
		tracker.seenHit(1200, BOSS, 1, "Vorkath", true, 50);

		FightReport r = report(tracker.getCurrent(), 10_000);
		assertEquals(100, r.getTotalDamage());
		assertEquals(30, r.row("Me").damage);
		assertEquals(20, r.row("Friend").damage);
		assertEquals(50, r.row(FightReport.UNKNOWN_NAME).damage);
		assertEquals(30.0, r.row("Me").percent, D);
		assertEquals(50.0, r.row(FightReport.UNKNOWN_NAME).percent, D);

		List<FightReport.PlayerRow> bars = r.sorted(MeterMode.DAMAGE);
		assertEquals(FightReport.UNKNOWN_NAME, bars.get(0).name);
		assertEquals("Me", bars.get(1).name);
		assertEquals("Friend", bars.get(2).name);
	}

	@Test
	public void partyHitOnTargetIDontSeeGivesNoNegativeUnknown()
	{
		myHit(0, RAT, false, 5);
		partyHit(600, "Friend", "301:99", false, 40, false);

		FightReport r = report(tracker.getCurrent(), 6000);
		assertEquals(45, r.getTotalDamage());
		assertNull(r.row(FightReport.UNKNOWN_NAME));
	}

	@Test
	public void poisonGetsItsOwnRow()
	{
		myHit(0, RAT, false, 10);
		tracker.effectHit(600, RAT, 1, "Rat", false, 6);

		FightReport r = report(tracker.getCurrent(), 6000);
		assertEquals(6, r.row(FightReport.EFFECTS_NAME).damage);
		assertNull(r.row(FightReport.UNKNOWN_NAME));
		assertEquals(16, r.getTotalDamage());
	}

	@Test
	public void effectsBeforeAFightAreIgnored()
	{
		tracker.effectHit(0, RAT, 1, "Rat", false, 6);
		assertNull(tracker.getCurrent());
	}

	@Test
	public void othersHittingNormalNpcDoNotStartAFight()
	{
		tracker.seenHit(0, RAT, 1, "Rat", false, 10);
		assertNull(tracker.getCurrent());
	}

	@Test
	public void strangersOnABossStartAFightButItIsThrownAwayWithoutOurDamage()
	{
		tracker.seenHit(0, BOSS, 1, "Vorkath", true, 10);
		assertNotNull(tracker.getCurrent());
		tracker.tick(20_000);
		assertNull(tracker.getCurrent());
		assertTrue(tracker.getHistory().isEmpty());
		assertTrue(ended.isEmpty());
	}

	@Test
	public void bossDeathEndsTheFight()
	{
		myHit(0, BOSS, true, 50);
		myHit(6000, BOSS, true, 50);
		tracker.npcDied(7200, BOSS, true);

		assertNull(tracker.getCurrent());
		assertEquals(1, ended.size());
		Fight f = ended.get(0);
		assertEquals(7200, f.endMs);
		assertEquals("Boss died", f.endReason);
		assertEquals(7200, f.durationMs(99_999));
		assertEquals("Vorkath", f.title());
	}

	@Test
	public void normalNpcDeathDoesNotEndTheFight()
	{
		myHit(0, RAT, false, 5);
		tracker.npcDied(600, RAT, false);
		assertNotNull(tracker.getCurrent());
	}

	@Test
	public void fightWithTwoBossesEndsWhenBothAreDead()
	{
		String other = "301:11";
		myHit(0, BOSS, true, 10);
		myHit(600, other, true, 10);
		tracker.npcDied(1200, BOSS, true);
		assertNotNull(tracker.getCurrent());
		tracker.npcDied(1800, other, true);
		assertNull(tracker.getCurrent());
	}

	@Test
	public void lateReportFromPartyGoesIntoTheEndedFight()
	{
		myHit(0, BOSS, true, 50);
		tracker.npcDied(3000, BOSS, true);
		// network delay: the friend's last hit arrives after the boss died
		partyHit(3500, "Friend", BOSS, true, 25, false);
		tracker.heal(3600, "Friend", PlayerKind.PARTY, HealType.FOOD, 18);

		assertNull("no new fight started", tracker.getCurrent());
		Fight f = tracker.getHistory().get(0);
		assertEquals(25, f.players.get("Friend").byTarget.get(BOSS).damage);
		assertEquals(18, f.players.get("Friend").healFood);
	}

	@Test
	public void veryLateReportStartsANewFight()
	{
		myHit(0, BOSS, true, 50);
		tracker.npcDied(3000, BOSS, true);
		partyHit(3000 + FightTracker.LATE_REPORT_MS + 1, "Friend", BOSS, true, 25, false);
		assertNotNull(tracker.getCurrent());
	}

	@Test
	public void idleTimeoutEndsWhenTheClockStopped()
	{
		myHit(1000, RAT, false, 5);
		myHit(3000, RAT, false, 5);
		tracker.tick(12_999);
		assertNotNull(tracker.getCurrent());
		tracker.tick(13_000);
		assertNull(tracker.getCurrent());
		Fight f = tracker.getHistory().get(0);
		// last hit + pause time (10 s): the same time the live clock showed
		assertEquals(13_000, f.endMs);
		assertEquals(12_000, f.durationMs(99_999));
		assertTrue(f.endReason.startsWith("No hits"));
	}

	@Test
	public void bossOnlyModeHidesOtherTargets()
	{
		myHit(0, BOSS, true, 40);
		myHit(600, RAT, false, 10);
