		assertEquals(100.0 * 11 / 20, r.row("Me").overhealPercent(), D);
		assertEquals(100.0 * 2 / 22, r.row("Friend").overhealPercent(), D);
		assertEquals(100.0 * 13 / 42, r.groupOverhealPercent(), D);
