package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import net.runelite.client.util.Filepath;

public class HistoryStoreTest
{
	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	private Fight sampleFight()
	{
		FightTracker t = new FightTracker();
		t.playerHit(0, "Me", PlayerKind.LOCAL, "301:5", 8059, "Vorkath", true, 44, false);
		t.seenHit(0, "301:5", 8059, "Vorkath", true, 44);
		t.playerHit(600, "Friend", PlayerKind.PARTY, "301:5", 8059, "Vorkath", true, 30, false);
		t.seenHit(600, "301:5", 8059, "Vorkath", true, 30);
		t.seenHit(1200, "301:5", 8059, "Vorkath", true, 12);
		t.heal(1200, "Me", PlayerKind.LOCAL, HealType.FOOD, 22);
		t.damageTaken(1200, "Me", PlayerKind.LOCAL, 9);
		t.npcDied(3000, "301:5", true);
		return t.getHistory().get(0);
	}

	/** Tests only: the plugin gets its folder from RuneLite (Plugin.getPluginDirectory). */
	private static Filepath rooted(Path dir)
	{
		return Filepath.Unchecked.getRooted(dir);
	}

	@Test
	public void saveAndLoadGivesTheSameNumbers() throws Exception
	{
		Path dir = folder.getRoot().toPath().resolve("goldendps");
		HistoryStore store = new HistoryStore(new Gson(), rooted(dir));
		store.save(12345L, Collections.singletonList(sampleFight()), 1000);

		assertTrue(Files.exists(dir.resolve("12345.json")));
		assertFalse("temp file is gone", Files.exists(dir.resolve("12345.json.tmp")));

		List<Fight> loaded = store.load(12345L);
		assertEquals(1, loaded.size());
		FightReport r = FightReport.of(loaded.get(0), false, 0);
		assertEquals(44, r.row("Me").damage);
		assertEquals(30, r.row("Friend").damage);
		assertEquals(12, r.row(FightReport.UNKNOWN_NAME).damage);
		assertEquals(22, r.row("Me").healing);
		assertEquals(9, r.row("Me").damageTaken);
		assertEquals(PlayerKind.LOCAL, r.row("Me").kind);
		assertEquals(3000, loaded.get(0).durationMs(0));
		assertEquals("Vorkath", loaded.get(0).title());
	}

	@Test
	public void accountsHaveTheirOwnFile() throws Exception
	{
		HistoryStore store = new HistoryStore(new Gson(), rooted(folder.getRoot().toPath()));
		store.save(1L, Collections.singletonList(sampleFight()), 0);
		assertEquals(1, store.load(1L).size());
		assertTrue(store.load(2L).isEmpty());
	}

	@Test
	public void brokenFileIsKeptAndHistoryStartsEmpty() throws Exception
	{
		Path dir = folder.getRoot().toPath();
		Files.write(dir.resolve("7.json"), "{ not json".getBytes(StandardCharsets.UTF_8));
		HistoryStore store = new HistoryStore(new Gson(), rooted(dir));

		assertTrue(store.load(7L).isEmpty());
		try (Stream<Path> files = Files.list(dir))
		{
			assertTrue(files.anyMatch(p -> p.getFileName().toString().startsWith("7.broken-")));
		}
	}

	@Test
	public void trackerKeepsLoadedHistory() throws Exception
	{
		HistoryStore store = new HistoryStore(new Gson(), rooted(folder.getRoot().toPath()));
		store.save(3L, Collections.singletonList(sampleFight()), 0);

		FightTracker t = new FightTracker();
		t.setHistory(store.load(3L));
		assertEquals(1, t.getHistory().size());
		assertEquals("Vorkath", t.getDisplayFight().title());
		// old fights are from another session: not in this session's total
		assertEquals(null, t.getSessionTotal(0));
	}

	@Test
	public void recordsAreSavedInTheirOwnFile() throws Exception
	{
		HistoryStore store = new HistoryStore(new Gson(), rooted(folder.getRoot().toPath()));
		assertTrue(store.loadRecords(7) == null);
		BossRecords r = new BossRecords();
		BossRecords.Kill k = new BossRecords.Kill();
		k.boss = "Zulrah";
		k.timeMs = 61_000;
		k.myDps = 5.5;
		r.add(k);
		store.saveRecords(7, r);
		BossRecords back = store.loadRecords(7);
		assertEquals(61_000, back.get("Zulrah", false).fastestMs);
		assertEquals(1, back.get("Zulrah", false).kills);
		assertTrue("fights file untouched", store.load(7).isEmpty());
	}

	@Test
	public void monsterStatsAreSavedInTheirOwnFile() throws Exception
	{
		HistoryStore store = new HistoryStore(new Gson(), rooted(folder.getRoot().toPath()));
		assertTrue(store.loadMonsters(7).byName.isEmpty());
		MonsterStats stats = new MonsterStats();
		MonsterStats.Monster m = new MonsterStats.Monster();
		m.name = "Gargoyle";
		m.kills = 3;
		m.attacks.add(25, false);
		m.weapons.put("Bow", m.attacks.copy());
		stats.byName.put(m.name, m);
		store.saveMonsters(7, stats);
		MonsterStats.Monster back = store.loadMonsters(7).byName.get("Gargoyle");
		assertEquals(3, back.kills);
		assertEquals(25, back.weapons.get("Bow").biggestHit);
		assertTrue("records file untouched", store.loadRecords(7) == null);
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Before;
import org.junit.Test;

public class HitAttributorTest
{
	private static final String BOSS = "301:10";
	private static final String RAT = "301:20";
	private HitAttributor a;

	@Before
	public void setUp()
	{
		a = new HitAttributor();
	}

	@Test
	public void meleeHitGoesToTheAttacker()
	{
		a.attack(100, "Bob", BOSS);
		assertEquals("Bob", a.assign(101, BOSS));
	}

	@Test
	public void oneAttackGivesOneHit()
	{
		a.attack(100, "Bob", BOSS);
		assertEquals("Bob", a.assign(101, BOSS));
		assertNull("next tick: no attack left", a.assign(102, BOSS));
	}

	@Test
	public void twoPlayersOldestAttackFirst()
	{
		a.attack(100, "Bob", BOSS);   // ranged, lands later
		a.attack(101, "Ann", BOSS);
		assertEquals("Bob", a.assign(103, BOSS));
		assertEquals("Ann", a.assign(104, BOSS));
	}

	@Test
	public void attackOnOtherNpcDoesNotMatch()
	{
		a.attack(100, "Bob", RAT);
		assertNull(a.assign(101, BOSS));
		assertEquals("Bob", a.assign(101, RAT));
	}

	@Test
	public void tooOldAttackIsForgotten()
	{
		a.attack(100, "Bob", BOSS);
		assertNull(a.assign(100 + HitAttributor.MAX_DELAY_TICKS + 1, BOSS));
	}

	@Test
	public void scytheThreeHitsplatsSameTick()
	{
		a.attack(100, "Bob", BOSS);
		assertEquals("Bob", a.assign(101, BOSS));
		assertEquals("Bob", a.assign(101, BOSS));
		assertEquals("Bob", a.assign(101, BOSS));
	}

	@Test
	public void extraHitWithTwoAttackersLandedIsUnknown()
	{
		a.attack(100, "Bob", BOSS);
		a.attack(100, "Ann", BOSS);
		assertEquals("Bob", a.assign(101, BOSS));
		assertEquals("Ann", a.assign(101, BOSS));
		assertNull(a.assign(101, BOSS));
	}

	@Test
	public void animationTwiceInOneAttackIsOneAttack()
	{
		a.attack(100, "Bob", BOSS);
		a.attack(101, "Bob", BOSS); // for example a block animation right after
		assertEquals("Bob", a.assign(102, BOSS));
		assertNull(a.assign(103, BOSS));
	}
}

