package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Test;

public class KillRatesTest
{
	private static final double D = 0.01;

	/** A Vorkath kill from start to start + 60 s, hitting every 5 s. */
	private static void vorkath(FightTracker t, long start, String key)
	{
		for (long ms = start; ms < start + 60_000; ms += 5000)
		{
			t.playerHit(ms, "Me", PlayerKind.LOCAL, key, 1, "Vorkath", true, 50, false);
		}
		t.npcDied(start + 60_000, key, true);
	}

	@Test
	public void killsPerHourFromTheFirstStartUntilNow()
	{
		FightTracker t = new FightTracker();
		vorkath(t, 0, "1:1");
		vorkath(t, 120_000, "1:2");
		vorkath(t, 240_000, "1:3");
		List<KillRates.Rate> rates = KillRates.of(t.getSessionFights(), 300_000);
		assertEquals(1, rates.size());
		KillRates.Rate r = rates.get(0);
		assertEquals(KillRates.Kind.BOSS, r.kind);
		assertEquals("Vorkath", r.name);
		assertEquals(3, r.kills);
		// 3 kills in 300 s = 36 per hour
		assertEquals(36.0, r.perHour, D);
		assertTrue(r.averageMs >= 55_000 && r.averageMs <= 60_000);
	}

	@Test
	public void theRateDropsWhileYouDoSomethingElse()
	{
		FightTracker t = new FightTracker();
		vorkath(t, 0, "1:1");
		assertEquals(60.0, KillRates.of(t.getSessionFights(), 60_000).get(0).perHour, D);
		assertEquals(1.0, KillRates.of(t.getSessionFights(), 3_600_000).get(0).perHour, D);
	}

	@Test
	public void raidsCountCompletionsAndTheirBossesCountAsKills()
	{
		FightTracker t = new FightTracker();
		for (int run = 0; run < 2; run++)
		{
			long start = run * 1_800_000L;
			t.startRaid(start, "Theatre of Blood");
			vorkath(t, start + 1000, "1:" + run);
			t.endRaid(start + 900_000, "Left the raid");
		}
		Fight last = t.getHistory().get(0);
		List<KillRates.Rate> rates = KillRates.of(t.getSessionFights(), last.endMs);
		KillRates.Rate raid = rates.stream().filter(r -> r.kind == KillRates.Kind.RAID).findFirst().get();
		assertEquals(2, raid.kills);
		assertEquals("Theatre of Blood", raid.name);
		// 2 completions from the first raid start to the last hit of the second raid
		assertTrue("a raid ends with its last hit", last.endMs < 2_700_000);
		assertEquals(2 * 3_600_000.0 / (last.endMs - 1000), raid.perHour, D);
		assertEquals(2, rates.stream().filter(r -> r.kind == KillRates.Kind.BOSS).findFirst().get().kills);
	}

	@Test
	public void aNewSessionStartsFromZero()
	{
		FightTracker t = new FightTracker();
		vorkath(t, 0, "1:1");
		t.resetSession(70_000);
		assertTrue(KillRates.of(t.getSessionFights(), 80_000).isEmpty());
	}

	@Test
	public void monstersCountPerName()
	{
		FightTracker t = new FightTracker();
		t.playerHit(1000, "Me", PlayerKind.LOCAL, "1:1", 2, "Cow", false, 8, false);
		t.npcDied(4000, "1:1", false);
		t.playerHit(5000, "Me", PlayerKind.LOCAL, "1:2", 2, "Cow", false, 8, false);
		t.npcDied(9000, "1:2", false);
		t.playerHit(9000, "Me", PlayerKind.LOCAL, "1:3", 3, "Goblin", false, 5, false);
		t.endNow(12_000, "test");
		List<KillRates.Rate> rates = KillRates.of(t.getSessionFights(), 9000);
		KillRates.Rate cow = rates.get(0);
		assertEquals("Cow", cow.name);
		assertEquals(KillRates.Kind.MONSTER, cow.kind);
		assertEquals(2, cow.kills);
		// 2 cows in 8 s = 900 per hour
		assertEquals(900.0, cow.perHour, D);
		assertEquals("the goblin did not die", 1, rates.size());
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class MonsterStatsTest
{
	private final FightTracker tracker = new FightTracker();
	private final MonsterStats stats = new MonsterStats();

	/** Kills one monster as the plugin does: 3 hits and 1 miss with the bow, 1 spec hit, 2.4 s apart. */
	private void kill(long start, String key, String name, int hit)
	{
		long now = start;
		for (int i = 0; i < 3; i++, now += 2400)
		{
			tracker.playerHit(now, "Me", PlayerKind.LOCAL, key, 1, name, false, hit, false, "Bow");
		}
		tracker.playerHit(now, "Me", PlayerKind.LOCAL, key, 1, name, false, 0, true, "Bow");
		tracker.playerHit(now += 2400, "Me", PlayerKind.LOCAL, key, 1, name, false, 40, false, "Claws (spec)");
		tracker.playerHit(now, "Friend", PlayerKind.PARTY, key, 1, name, false, 99, false, "Sword");
		Fight fight = tracker.getCurrent();
		tracker.npcDied(now, key, false);
		stats.addKill(fight, key);
	}

	@Test
	public void countsEachKillTheMomentItDies()
	{
		kill(1000, "1:1", "Gargoyle", 10);
		assertEquals(1, stats.byName.get("Gargoyle").kills);
		kill(20_000, "1:2", "Gargoyle", 20);
		MonsterStats.Monster m = stats.byName.get("Gargoyle");

		assertEquals(2, m.kills);
		// first hit to death: four attacks 2.4 s apart
		assertEquals(9600, m.fastestMs);
		assertEquals(9600, m.averageMs());
		// only your own hits: the friend's 99 is left out
		assertEquals(40, m.attacks.biggestHit);
		assertEquals(8, m.attacks.hits);
		assertEquals(2, m.attacks.misses);
		assertEquals(30 + 60 + 80, m.attacks.damage);
		assertEquals(6, m.weapons.get("Bow").hits);
		assertEquals(2, m.weapons.get("Bow").misses);
		assertEquals(20, m.weapons.get("Bow").biggestHit);
		assertEquals(2, m.weapons.get("Claws (spec)").hits);
	}

	@Test
	public void aRespawnOnTheSameIndexCountsOnlyItsOwnHits()
	{
		kill(1000, "1:1", "Gargoyle", 10);
		// the same death reported again is no new kill
		stats.addKill(tracker.getCurrent(), "1:1");
		kill(20_000, "1:1", "Gargoyle", 20);
		MonsterStats.Monster m = stats.byName.get("Gargoyle");
		assertEquals(2, m.kills);
		assertEquals(8, m.attacks.hits);
		assertEquals(30 + 60 + 80, m.attacks.damage);
		assertEquals(6, m.weapons.get("Bow").hits);
		// the respawn's time is not known: it shares the first monster's first hit
		assertEquals(1, m.timedKills);
		assertEquals(9600, m.averageMs());
	}

	@Test
	public void aMonsterYouDidNotHitIsNoKill()
	{
		tracker.playerHit(1000, "Friend", PlayerKind.PARTY, "1:1", 1, "Gargoyle", false, 50, false, "Sword");
		Fight fight = tracker.getCurrent();
		tracker.npcDied(2000, "1:1", false);
		stats.addKill(fight, "1:1");
		assertNull(stats.byName.get("Gargoyle"));
	}

	@Test
	public void entriesJoinMonstersAndPersonalBestsLastKillFirst()
	{
		kill(1000, "1:1", "Vorkath", 10);
		kill(100_000, "1:2", "Gargoyle", 10);
		BossRecords.Record solo = new BossRecords.Record();
		solo.boss = "Vorkath";
		solo.lastMs = 500;
		BossRecords.Record raid = new BossRecords.Record();
		raid.boss = "Chambers of Xeric";
		raid.party = true;
		raid.lastMs = 200_000;
		List<BossRecords.Record> records = new ArrayList<>();
		records.add(solo);
		records.add(raid);

		List<MonsterStats.Entry> entries = stats.entries(records);
		assertEquals(3, entries.size());
		assertEquals("Chambers of Xeric", entries.get(0).name);
		assertNull(entries.get(0).stats);
		assertEquals(raid, entries.get(0).party);
		assertEquals("Gargoyle", entries.get(1).name);
		assertEquals("Vorkath", entries.get(2).name);
		assertEquals(solo, entries.get(2).solo);
		assertEquals(1, entries.get(2).stats.kills);
		solo.kills = 143;
		assertEquals(143, entries.get(2).kills());
		assertEquals(1, entries.get(1).kills());
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class PartyLeaderTest
{
	@Test
	public void aloneInANewPartyYouLead()
	{
		PartyLeader l = new PartyLeader();
		l.joined(50, 1000);
		assertFalse("wait for an answer first", l.tick(2000, Collections.singletonList(50L)));
		assertFalse(l.isLeader());
		assertTrue(l.tick(4000, Collections.singletonList(50L)));
		assertTrue(l.isLeader());
	}

	@Test
	public void joiningAPartyTheLeaderTellsYou()
	{
		PartyLeader l = new PartyLeader();
		l.joined(50, 1000);
		l.announce(20, 20);
		assertEquals(20, l.getLeader());
		assertFalse(l.isLeader());
		// a later claim from someone who is not the leader is ignored
		l.announce(30, 30);
		assertEquals(20, l.getLeader());
		// the leader can hand it over
		l.announce(20, 50);
		assertTrue(l.isLeader());
	}

	@Test
	public void nobodyAnswersLowestGoldenDpsIdLeads()
	{
		PartyLeader l = new PartyLeader();
		l.joined(50, 1000);
		l.sawPlugin(40);
		// 10 is in the party but has no GoldenDPS: cannot lead
		assertTrue(l.tick(5000, Arrays.asList(10L, 40L, 50L)));
		assertEquals(40, l.getLeader());
	}

	@Test
	public void leaderLeavesNextOneIsPicked()
	{
		PartyLeader l = new PartyLeader();
		l.joined(50, 1000);
		l.announce(20, 20);
		l.sawPlugin(30);
		l.memberLeft(20, Arrays.asList(30L, 50L));
		assertEquals(30, l.getLeader());
	}

	@Test
	public void onlyTheLeaderCanKickYou()
	{
		PartyLeader l = new PartyLeader();
		l.joined(50, 1000);
		l.announce(20, 20);
		assertFalse("not the leader", l.acceptKick(30, 50));
		assertFalse("kick for someone else", l.acceptKick(20, 60));
		assertTrue(l.acceptKick(20, 50));
	}

	@Test
	public void theLeaderCannotKickThemself()
	{
		PartyLeader l = new PartyLeader();
		l.joined(50, 1000);
		l.tick(5000, Collections.singletonList(50L));
		assertFalse(l.acceptKick(50, 50));
	}

	@Test
	public void leavingForgetsEverything()
	{
		PartyLeader l = new PartyLeader();
		l.joined(50, 1000);
		l.tick(5000, Collections.singletonList(50L));
		l.left();
		assertFalse(l.isJoined());
		assertFalse(l.isLeader());
		assertFalse(l.hasPlugin(50));
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class PartyNoticesTest
{
	private static Map<Long, String> members(Object... idName)
	{
		Map<Long, String> m = new HashMap<>();
		for (int i = 0; i < idName.length; i += 2)
		{
			m.put(((Number) idName[i]).longValue(), (String) idName[i + 1]);
		}
		return m;
	}

	@Test
	public void peopleAlreadyInThePartyAreNotAnnounced()
	{
		PartyNotices n = new PartyNotices();
		assertTrue(n.tick(0, 1, members()).isEmpty());
		// their names arrive 2 s later
		assertTrue(n.tick(2000, 1, members(5, "Zezima")).isEmpty());
	}

	@Test
	public void joinAndLeave()
	{
		PartyNotices n = new PartyNotices();
		n.tick(0, 1, members());
		List<PartyNotices.Notice> j = n.tick(10_000, 1, members(5, "Monster NRGs"));
		assertEquals(1, j.size());
		assertEquals("Monster NRGs", j.get(0).name);
		assertTrue(j.get(0).joined);
		assertTrue("only once", n.tick(11_000, 1, members(5, "Monster NRGs")).isEmpty());

		assertTrue("not yet: maybe a world hop", n.tick(20_000, 1, members()).isEmpty());
		List<PartyNotices.Notice> l = n.tick(20_000 + PartyNotices.BACK_MS, 1, members());
		assertEquals(1, l.size());
		assertFalse(l.get(0).joined);
	}

	@Test
	public void aHopOrReconnectIsNotAnnounced()
	{
		PartyNotices n = new PartyNotices();
		n.tick(0, 1, members());
		n.tick(10_000, 1, members(5, "Jern Henrik"));
		n.tick(20_000, 1, members());
		// back with a new member id a few seconds later
		assertTrue(n.tick(23_000, 1, members(9, "Jern Henrik")).isEmpty());
		assertTrue(n.tick(60_000, 1, members(9, "Jern Henrik")).isEmpty());
	}

	@Test
	public void kickedMembersGetNoLeftNotice()
	{
		PartyNotices n = new PartyNotices();
		n.tick(0, 1, members());
		n.tick(10_000, 1, members(5, "Monster NRGs"));
		n.kicked(5);
		assertTrue(n.tick(12_000, 1, members()).isEmpty());
	}

	@Test
	public void aNewPartyStartsQuietAgain()
	{
		PartyNotices n = new PartyNotices();
		n.tick(0, 1, members());
		n.tick(10_000, 1, members(5, "A"));
		// you joined another party: new member id
		assertTrue(n.tick(11_000, 2, members(7, "B")).isEmpty());
	}

	@Test
	public void theOneWhoJoinsHearsWhoIsInThePartyOnce()
	{
		PartyNotices n = new PartyNotices();
		n.tick(0, 1, members());
		assertTrue(n.welcome(0) == null);
		n.tick(2000, 1, members(5, "Zezima", 6, "Bob"));
		n.tick(PartyNotices.QUIET_MS, 1, members(5, "Zezima", 6, "Bob"));
		List<String> w = n.welcome(PartyNotices.QUIET_MS);
		assertEquals("you are in the party \"tjeerocka\" with Bob, Zezima.", PartyNotices.welcomeText("tjeerocka", w));
		assertTrue("only once", n.welcome(9000) == null);
		assertEquals("you are in the party \"x\". Nobody else is in it yet.",
			PartyNotices.welcomeText("x", new java.util.ArrayList<>()));
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class RaidFightTest
{
	private static final String MAIDEN = "301:1";
	private static final String BLOAT = "301:2";
	private static final String CRAB = "301:3";
	private static final String TOB = "Theatre of Blood";

	private final List<Fight> ended = new ArrayList<>();

	private FightTracker tracker()
	{
		FightTracker t = new FightTracker();
		t.setListener(ended::add);
		return t;
	}

	private static void hit(FightTracker t, long ms, String key, String name, boolean boss, int amount)
	{
		t.playerHit(ms, "Me", PlayerKind.LOCAL, key, 1, name, boss, amount, false);
	}

	@Test
	public void aRaidRunsOnTheGameClockAndEndsWithItsLastHit()
	{
		FightTracker t = tracker();
		t.startRaid(0, TOB);
		hit(t, 1000, MAIDEN, "The Maiden of Sugadinti", true, 50);
		hit(t, 121_000, BLOAT, "Pestilent Bloat", true, 50);
		t.endRaid(300_000, "Left the raid");
		Fight raid = ended.get(ended.size() - 1);
		assertEquals(TOB, raid.title());
		assertEquals("2 minutes between rooms count, looting after does not", 120_000, raid.durationMs(300_000));
	}

	@Test
	public void aRaidListsItsBossFightsInOrder()
	{
		FightTracker t = tracker();
		t.startRaid(0, TOB);
		hit(t, 1000, MAIDEN, "The Maiden of Sugadinti", true, 50);
		t.npcDied(60_000, MAIDEN, true);
		hit(t, 90_000, BLOAT, "Pestilent Bloat", true, 50);
		Fight raid = t.getCurrent();
		List<Fight> parts = t.partsOf(raid);
		assertEquals(2, parts.size());
		assertEquals("The Maiden of Sugadinti", parts.get(0).title());
		assertSame("the running boss fight comes last", t.getBossPart(), parts.get(1));
	}

	@Test
	public void theRaidFightStartsWhenTheGameStartsTheRaid()
	{
		FightTracker t = tracker();
		t.startRaid(0, "Chambers of Xeric");
		t.raidBegan(5000);
		hit(t, 25_000, "301:7", "Tekton", true, 50);
		assertEquals(5000, t.getCurrent().startMs);
		assertEquals("from the game's start to the last hit", 20_000, t.getCurrent().durationMs(25_000));
	}

	@Test
	public void olmIsOneKillOverAllItsPhases()
	{
		FightTracker t = tracker();
		t.startRaid(0, "Chambers of Xeric");
		hit(t, 1000, "301:7", "Great Olm (Left claw)", true, 50);
		t.npcDied(5000, "301:7", true);
		assertNull("a phase ends, Olm goes on", lastEnded(t));
		hit(t, 60_000, "301:8", "Great Olm (Right claw)", true, 50);
		t.npcDied(65_000, "301:8", true);
		hit(t, 90_000, "301:9", "Great Olm", true, 80);
		t.npcDied(95_000, "301:9", true);
		Fight olm = ended.get(ended.size() - 1);
		assertEquals("Great Olm", olm.title());
		assertNotNull(BossRecords.kill(olm));
		assertEquals(1, ended.stream().filter(f -> f.partOf != null).count());
	}

	@Test
	public void theVespulaPortalIsNamedAfterItsRoom()
	{
		assertEquals("Vespula portal", Fight.bossName("Abyssal portal"));
	}

	private Fight lastEnded(FightTracker t)
	{
		return ended.stream().filter(f -> f.partOf != null).findFirst().orElse(null);
	}

	@Test
	public void raidStartEndsTheOldFight()
	{
		FightTracker t = tracker();
		hit(t, 1000, CRAB, "Goblin", false, 5);
		t.startRaid(2000, TOB);
		assertNull(t.getCurrent());
		assertEquals("Raid started", t.getHistory().get(0).endReason);
	}

	@Test
	public void oneFightForTheWholeRaidAndOneForEachBoss()
	{
		FightTracker t = tracker();
		t.startRaid(0, TOB);
		hit(t, 1000, MAIDEN, "The Maiden of Sugadinti", true, 50);
		hit(t, 2000, CRAB, "Nylocas Matomenos", false, 10);
		assertNotNull(t.getBossPart());
		t.npcDied(60_000, MAIDEN, true);

		// the raid goes on after the boss died, the boss has its own fight
		Fight raid = t.getCurrent();
		assertNotNull(raid);
		assertEquals(TOB, raid.title());
		assertNull(t.getBossPart());
		Fight maiden = t.getHistory().get(0);
		assertEquals(raid.id, maiden.partOf);
		assertEquals("a boss names the fight without +1", "The Maiden of Sugadinti", maiden.title());
		assertEquals(60, maiden.knownDamage());
		assertSame(maiden, ended.get(0));

		// 6 minutes later (walking, AFK): the raid is still running
		t.tick(400_000);
		assertNotNull(t.getCurrent());
		assertSame("boss meter: last boss of this raid", maiden, t.getBossDisplayFight());

		// next boss: a new boss fight
		hit(t, 420_000, BLOAT, "Pestilent Bloat", true, 40);
		assertEquals("Pestilent Bloat", t.getBossDisplayFight().title());
		t.npcDied(450_000, BLOAT, true);

		t.endRaid(500_000, "Left the raid");
		assertNull(t.getCurrent());
		assertNull(t.getRaid());
		Fight done = t.getHistory().get(0);
		assertEquals(TOB, done.title());
		assertEquals(100, done.knownDamage());
		assertEquals("Left the raid", done.endReason);
		assertSame("main meter shows the raid, not the last boss", done, t.getDisplayFight());
	}

	@Test
	public void sessionCountsRaidBossesOnce()
	{
		FightTracker t = tracker();
		t.startRaid(0, TOB);
		hit(t, 1000, MAIDEN, "The Maiden of Sugadinti", true, 50);
		t.npcDied(5000, MAIDEN, true);
		t.endRaid(10_000, "done");
		Fight s = t.getSessionTotal(20_000);
		assertEquals(1, s.mergedFights);
		assertEquals(50, s.knownDamage());
	}

	@Test
	public void raidPbsComeFromTheBossFightsOnly()
	{
		FightTracker t = tracker();
		t.startRaid(0, TOB);
		for (int ms = 1000; ms <= 31_000; ms += 5000)
		{
			hit(t, ms, MAIDEN, "The Maiden of Sugadinti", true, 50);
		}
		t.npcDied(31_000, MAIDEN, true);
		t.endRaid(40_000, "done");
		BossRecords.Kill boss = BossRecords.kill(ended.get(0));
		assertNotNull(boss);
		assertEquals(30_000, boss.timeMs);
		assertNull("the raid itself is no boss kill", BossRecords.kill(ended.get(1)));
	}

	@Test
	public void wipeEndsTheBossFightAfterTheIdleTime()
	{
		FightTracker t = tracker();
		t.setIdleTimeoutMs(300_000);
		t.startRaid(0, TOB);
		hit(t, 1000, MAIDEN, "The Maiden of Sugadinti", true, 50);
		t.tick(302_000);
		assertNull(t.getBossPart());
		assertNotNull("raid still runs", t.getCurrent());
		assertTrue(t.getHistory().get(0).endReason.startsWith("No hits"));
	}

	@Test
	public void bossFightWithOnlyStrangersHitsIsNotKept()
	{
		FightTracker t = tracker();
		t.startRaid(0, TOB);
		hit(t, 1000, CRAB, "Nylocas Matomenos", false, 10);
		t.seenHit(2000, MAIDEN, 1, "The Maiden of Sugadinti", true, 30);
		Fight bossPart = t.getBossPart();
		assertNotNull("a hit seen on a boss starts the boss fight", bossPart);
		assertEquals(30, bossPart.targets.get(MAIDEN).seenDamage);
		assertEquals("the raid fight sees it too", 30, t.getCurrent().targets.get(MAIDEN).seenDamage);

		t.endRaid(5000, "Left the raid");
		assertEquals("only the raid fight is kept", 1, ended.size());
		assertEquals(TOB, ended.get(0).title());
	}

	@Test
	public void outsideRaidsNothingChanges()
	{
		FightTracker t = tracker();
		hit(t, 1000, MAIDEN, "Vorkath", true, 50);
		assertNull(t.getBossPart());
		t.npcDied(2000, MAIDEN, true);
		assertNull(t.getCurrent());
		assertEquals(1, t.getHistory().size());
	}

	@Test
	public void monsterFightsCountTheOtherTargets()
	{
		FightTracker t = tracker();
		hit(t, 1000, CRAB, "Goblin", false, 5);
		hit(t, 2000, BLOAT, "Cow", false, 9);
		assertEquals("Cow +1", t.getCurrent().title());
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class RaidPartyTest
{
	private static final String TOB = "ToB";
	private static final String P1 = RaidParty.PREFIX + "tob 111";
	private static final String P2 = RaidParty.PREFIX + "tob 222";

	private static String tickUntilStable(RaidParty r, String name, String current)
	{
		RaidParty.Action action = RaidParty.Action.NONE;
		for (int i = 0; i < RaidParty.STABLE_TICKS; i++)
		{
			action = r.tick(name, current, false);
		}
		return action.join;
	}

	@Test
	public void everyoneGetsTheSameName()
	{
		String a = RaidParty.partyName(TOB, 302, Arrays.asList("Kurt Yoghurt", "Zezima", "", null));
		String b = RaidParty.partyName(TOB, 302, Arrays.asList("zezima", "Kurt Yoghurt"));
		assertEquals(a, b);
		assertTrue(a.startsWith("goldendps tob "));
	}

	@Test
	public void otherRaidWorldOrPeopleGiveAnotherName()
	{
		String base = RaidParty.partyName(TOB, 302, Arrays.asList("A", "B"));
		assertNotEquals(base, RaidParty.partyName("ToA", 302, Arrays.asList("A", "B")));
		assertNotEquals(base, RaidParty.partyName(TOB, 303, Arrays.asList("A", "B")));
		assertNotEquals(base, RaidParty.partyName(TOB, 302, Arrays.asList("A", "B", "C")));
	}

	@Test
	public void aloneIsNoParty()
	{
		assertNull(RaidParty.partyName(TOB, 302, Collections.singletonList("Kurt")));
		assertNull(RaidParty.partyName(TOB, 302, Collections.emptyList()));
	}

	@Test
	public void joinsOnceTheNamesAreStable()
	{
		RaidParty r = new RaidParty();
		for (int i = 1; i < RaidParty.STABLE_TICKS; i++)
		{
			assertNull(r.tick(P1, null, false).join);
		}
		assertEquals(P1, r.tick(P1, null, false).join);
		assertNull(r.tick(P1, P1, false).join);
	}

	@Test
	public void movesWhenTheRaidPartyChanges()
	{
		RaidParty r = new RaidParty();
		tickUntilStable(r, P1, null);
		assertEquals(P2, tickUntilStable(r, P2, P1));
	}

	@Test
	public void neverTouchesAManualParty()
	{
		RaidParty r = new RaidParty();
		for (int i = 0; i < 20; i++)
		{
			assertNull(r.tick(P1, "my friends", false).join);
			assertFalse(r.tick(null, "my friends", false).leave);
		}
	}

	@Test
	public void leavesOnceAfterTheRaid()
	{
		RaidParty r = new RaidParty();
		tickUntilStable(r, P1, null);
		for (int i = 1; i < RaidParty.LEAVE_TICKS; i++)
		{
			assertFalse(r.tick(null, P1, false).leave);
		}
		assertTrue(r.tick(null, P1, false).leave);
		assertFalse("only once", r.tick(null, P1, false).leave);
	}

	@Test
	public void staysInsideTheRaidWithoutAPartyId()
	{
		RaidParty r = new RaidParty();
		tickUntilStable(r, P1, null);
		for (int i = 0; i < 100; i++)
		{
			assertFalse(r.tick(null, P1, true).leave);
		}
		for (int i = 1; i < RaidParty.LEAVE_TICKS; i++)
		{
			assertFalse(r.tick(null, P1, false).leave);
		}
		assertTrue("leaves after the raid", r.tick(null, P1, false).leave);
	}

	@Test
	public void yourOwnPartyIsNeverLeftButARaidPartyReplacesIt()
	{
		String own = RaidParty.OWN_PREFIX + "blue cat";
		assertTrue(RaidParty.isAuto(own));
		assertTrue(RaidParty.isOwn(own));
		assertFalse(RaidParty.isOwn(P1));
		RaidParty r = new RaidParty();
		for (int i = 0; i < 3 * RaidParty.LEAVE_TICKS; i++)
		{
			assertFalse(r.tick(null, own, false).leave);
		}
		assertEquals("a raid party replaces your own party", P1, tickUntilStable(r, P1, own));
	}

	@Test
	public void insideCoxYouJoinTheRememberedParty()
	{
		RaidParty r = new RaidParty();
		tickUntilStable(r, P1, "my friends");    // in the lobby, still in your own party
		RaidParty.Action action = RaidParty.Action.NONE;
		for (int i = 0; i < RaidParty.STABLE_TICKS; i++)
		{
			// inside the raid the game shows no party id; you have left your party
			action = r.tick(null, null, true);
		}
		assertEquals(P1, action.join);
	}

	@Test
	public void aRememberedPartyIsUsedAfterARestartAndForgottenAfterTheRaid()
	{
		RaidParty r = new RaidParty();
		r.remember(P1);
		assertEquals(P1, tickUntilStableInRaid(r));
		for (int i = 0; i < RaidParty.LEAVE_TICKS; i++)
		{
			r.tick(null, P1, false);
		}
		assertNull(r.getRemembered());
		assertNull("outside a raid memory is not used", tickUntilStable(r, null, null));
	}

	private static String tickUntilStableInRaid(RaidParty r)
	{
		RaidParty.Action action = RaidParty.Action.NONE;
		for (int i = 0; i < RaidParty.STABLE_TICKS; i++)
		{
			action = r.tick(null, null, true);
		}
		return action.join;
	}

	@Test
	public void shortGapsWhileLoadingDoNotLeave()
	{
		RaidParty r = new RaidParty();
		tickUntilStable(r, P1, null);
		for (int i = 0; i < 30; i++)
		{
			assertFalse(r.tick(i % 5 == 0 ? P1 : null, P1, false).leave);
		}
		assertTrue(RaidParty.isAuto(P1));
		assertFalse(RaidParty.isAuto("my friends"));
	}

	@Test
	public void coxUsesTheRaidPartyId()
	{
		String a = RaidParty.coxPartyName(302, 12345, 0);
		assertEquals(a, RaidParty.coxPartyName(302, 12345, 3));
		assertTrue(a.startsWith(RaidParty.PREFIX + "cox "));
		assertNotEquals(a, RaidParty.coxPartyName(303, 12345, 3));
		assertNotEquals(a, RaidParty.coxPartyName(302, 999, 3));
		assertNull(RaidParty.coxPartyName(302, -1, 0));
		assertNull(RaidParty.coxPartyName(302, 12345, 1));
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class RaidPointsTest
{
	@Test
	public void readsThePointsMessage()
	{
		RaidPoints p = new RaidPoints();
		p.message(1000, "Total points: <col=ff0000>31,408</col>, Personal points: <col=ff0000>31,408</col> (100%)");
		assertEquals("31,408 pts", p.near(2000));
		p.message(1000, "Total points: 52,000, Personal points: 20,500 (39.4%)");
		assertEquals("20,500 of 52,000 pts", p.near(2000));
		assertNull("too long ago", p.near(1000 + KillCounts.NEAR_MS + 1));
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RaidZoneTest
{
	@Test
	public void regionsNeedAnInstance()
	{
		assertEquals(RaidZone.TOB, RaidZone.raidFor(12613, true));
		assertEquals(RaidZone.TFA, RaidZone.raidFor(16214, true));
		assertNull("same region but not instanced", RaidZone.raidFor(12613, false));
		assertNull("ToB lobby (Ver Sinhaza)", RaidZone.raidFor(14642, true));
	}

	@Test
	public void startsAtOnceAndEndsAfterSomeTicksOutside()
	{
		RaidZone z = new RaidZone();
		assertEquals(RaidZone.TOA, z.tick(RaidZone.TOA).start);
		assertNull(z.tick(RaidZone.TOA).start);
		// loading screen between rooms
		assertFalse(z.tick(null).end);
		assertNull(z.tick(RaidZone.TOA).start);
		for (int i = 1; i < RaidZone.LEAVE_TICKS; i++)
		{
			assertFalse(z.tick(null).end);
		}
		assertTrue(z.tick(null).end);
		assertNull(z.getInside());
	}

	@Test
	public void goingStraightToAnotherRaidStartsIt()
	{
		RaidZone z = new RaidZone();
		z.tick(RaidZone.TOB);
		assertEquals(RaidZone.COX, z.tick(RaidZone.COX).start);
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Test;

public class ReportFormatterTest
{
	private static final String BOSS = "301:5";

	/** Me 600, Friend 300, someone without the plugin 100, over 10 s (hits every 5 s). */
	private FightReport fight()
	{
		FightTracker t = new FightTracker();
		t.playerHit(1000, "Kurt Yoghurt", PlayerKind.LOCAL, BOSS, 1, "Vorkath", true, 300, false);
		t.seenHit(1000, BOSS, 1, "Vorkath", true, 300);
		t.playerHit(6000, "Kurt Yoghurt", PlayerKind.LOCAL, BOSS, 1, "Vorkath", true, 300, false);
		t.seenHit(6000, BOSS, 1, "Vorkath", true, 300);
		t.playerHit(6000, "Zezima", PlayerKind.PARTY, BOSS, 1, "Vorkath", true, 300, false);
		t.seenHit(6000, BOSS, 1, "Vorkath", true, 300);
		t.seenHit(6000, BOSS, 1, "Vorkath", true, 100);
		t.heal(6000, "Kurt Yoghurt", PlayerKind.LOCAL, HealType.FOOD, 60, 20);
		t.heal(6000, "Zezima", PlayerKind.PARTY, HealType.LIFESTEAL, 20);
		return FightReport.of(t.getCurrent(), false, 11_000);
	}

	@Test
	public void damageReport()
	{
		List<String> lines = ReportFormatter.lines(fight(), MeterMode.DAMAGE, "Vorkath", 5);
		assertEquals("Damage - Vorkath 0:10 - total 1,000 (100.0/s)", lines.get(0));
		assertEquals("1. Kurt Yoghurt 600 60.0/s 60%", lines.get(1));
		assertEquals("2. Zezima 300 30.0/s 30%", lines.get(2));
		assertEquals("3. Others (unknown) 100 10.0/s 10%", lines.get(3));
		assertEquals(4, lines.size());
	}

	@Test
	public void dpsReportPutsDpsFirst()
	{
		List<String> lines = ReportFormatter.lines(fight(), MeterMode.DPS, "Vorkath", 5);
		assertEquals("1. Kurt Yoghurt 60.0/s 600 60%", lines.get(1));
	}

	@Test
	public void healingReportHasOverhealing()
	{
		List<String> lines = ReportFormatter.lines(fight(), MeterMode.HEALING, "Vorkath", 5);
		// group: 80 healed + 20 wasted = 20% OH
		assertEquals("Healing - Vorkath 0:10 - total 80 OH 20%", lines.get(0));
		assertEquals("1. Kurt Yoghurt 60 OH 25% 75%", lines.get(1));
		assertEquals("2. Zezima 20 25%", lines.get(2));
		assertEquals(3, lines.size());
	}

	@Test
	public void soloIsOneLine()
	{
		Fight f = new Fight("s", "s", 0);
		f.player("Me", PlayerKind.LOCAL).addHit("1:1", 100, false);
		f.target("1:1", 1, "Vorkath", true).engaged = true;
		f.activity(10_000);
		f.finish(10_000, "test");
		List<String> lines = ReportFormatter.lines(FightReport.of(f, false, 10_000), MeterMode.DAMAGE,
			"Boss damage", "Vorkath", 5);
		assertEquals(1, lines.size());
		assertEquals("Boss damage - Vorkath 0:10 - total 100 (10.0/s)", lines.get(0));
	}

	@Test
	public void burnDamageDoesNotMakeAGroup()
	{
		FightTracker t = new FightTracker();
		t.playerHit(1000, "Me", PlayerKind.LOCAL, "1:1", 1, "Lesser demon", false, 40, false);
		t.effectHit(2000, "1:1", 1, "Lesser demon", false, 2);
		FightReport r = FightReport.of(t.getCurrent(), false, 3000);
		assertTrue(r.isSolo());
		assertEquals(1, ReportFormatter.lines(r, MeterMode.DAMAGE, "Damage", "Lesser demon", 5).size());
	}

	@Test
	public void theOverallReportGivesTheKills()
	{
		FightTracker t = new FightTracker();
		t.playerHit(1000, "Me", PlayerKind.LOCAL, "1:1", 1, "Grizzly bear", false, 30, false);
		t.npcDied(2000, "1:1", false);
		t.playerHit(3000, "Me", PlayerKind.LOCAL, "1:2", 1, "Grizzly bear", false, 30, false);
		t.npcDied(4000, "1:2", false);
		FightReport r = FightReport.of(t.getCurrent(), false, 5000);
		assertEquals("Overall damage - Grizzly bear 0:04 - total 60 - 2 kills",
			ReportFormatter.lines(r, MeterMode.DAMAGE, "Overall damage", "Grizzly bear", 5, true).get(0));
	}

	@Test
	public void topLimitsThePlayers()
	{
		List<String> lines = ReportFormatter.lines(fight(), MeterMode.DAMAGE, "Vorkath", 1);
		assertEquals(2, lines.size());
	}

	@Test
	public void emptyFightIsOnlyTheHeader()
	{
		List<String> lines = ReportFormatter.lines(fight(), MeterMode.DAMAGE_TAKEN, "Session", 5);
		assertEquals(1, lines.size());
		assertEquals("Damage taken - Session 0:10", lines.get(0));
	}

	@Test
	public void linesFitInOnePartyMessage()
	{
		FightTracker t = new FightTracker();
		String longName = "A very long name that goes on and on and on and on and on and on and on and on and on and on and on and on";
		t.playerHit(1000, longName, PlayerKind.LOCAL, BOSS, 1, "Vorkath", true, 300, false);
		FightReport r = FightReport.of(t.getCurrent(), false, 11_000);
		for (String line : ReportFormatter.lines(r, MeterMode.DAMAGE, longName, 5))
		{
			assertTrue(line.length() <= ReportFormatter.MAX_LINE);
		}
	}

	@Test
	public void headerUsesTheReportName()
	{
		List<String> lines = ReportFormatter.lines(fight(), MeterMode.DAMAGE, "Boss damage", "Vorkath", 5);
		assertEquals("Boss damage - Vorkath 0:10 - total 1,000 (100.0/s)", lines.get(0));
	}
}

